		// Find previous newline
		prev := -1
		for j := i - 1; j >= 0; j-- {
			if content[j] == '\n' {
				prev = j
				break
			}
		}
		next := len(content)
		for j := i + 1; j < len(content); j++ {
			if content[j] == '\n' {
				next = j
				break
			}
		}
		line := content[prev+1 : next]
		// Check if line contains alphanumeric
		hasAlpha := false
		for _, c := range line {
