func formatJSON2(summaries []LangSummary, cost, schedule, people float64, opts Options) string {
	type JSON2 struct {
		LanguageSummary          []LangSummary `json:"languageSummary"`
		EstimatedCost            float64       `json:"estimatedCost"`
		EstimatedScheduleMonths  float64       `json:"estimatedScheduleMonths"`
		EstimatedPeople          float64       `json:"estimatedPeople"`
		EstimatedLLMCost         *float64      `json:"estimatedLLMCost,omitempty"`
		EstimatedLLMInputTokens  *float64      `json:"estimatedLLMInputTokens,omitempty"`
		EstimatedLLMOutputTokens *float64      `json:"estimatedLLMOutputTokens,omitempty"`
		EstimatedLLMGenerationSeconds *float64 `json:"estimatedLLMGenerationSeconds,omitempty"`
		EstimatedLLMReviewHours *float64 `json:"estimatedLLMReviewHours,omitempty"`
		EstimatedLLMPreset      *string  `json:"estimatedLLMPreset,omitempty"`
		EstimatedLLMAverageComplexityMultiplier *float64 `json:"estimatedLLMAverageComplexityMultiplier,omitempty"`
		EstimatedLLMCycles      *float64 `json:"estimatedLLMCycles,omitempty"`
	}
	j := JSON2{
		LanguageSummary:         summaries,
		EstimatedCost:           cost,
		EstimatedScheduleMonths: schedule,
		EstimatedPeople:         people,
	}
	if opts.Locomo {
		// Compute LOCOMO details for json2
		// Simplified: compute tokens etc using same logic as formatLOCOMO but for total
		var total LangSummary
		for _, s := range summaries {
			total.Lines += s.Lines
			total.Complexity += s.Complexity
		}
		// Use preset
		var inputPrice, outputPrice float64
		var tps float64
		switch strings.ToLower(opts.LocomoPreset) {
		case "small":
			inputPrice = 0.5
			outputPrice = 2
			tps = 100
		case "large":
			inputPrice = 10
			outputPrice = 30
			tps = 30
		case "local":
			inputPrice = 0
			outputPrice = 0
			tps = 15
		default:
			inputPrice = 3
			outputPrice = 15
			tps = 50
		}
		if opts.LocomoInputPrice != nil {
			inputPrice = *opts.LocomoInputPrice
		}
		if opts.LocomoOutputPrice != nil {
			outputPrice = *opts.LocomoOutputPrice
		}
		if opts.LocomoTps != nil {
			tps = *opts.LocomoTps
		}
		tokensPerLine := 15.0
		inputPerLine := 30.0
		complexityWeight := 2.0
		iterations := 1.5
		iterationWeight := 2.0
		if opts.LocomoConfig != "" {
			parts := strings.Split(opts.LocomoConfig, ",")
			if len(parts) == 5 {
				if v, err := strconv.ParseFloat(parts[0], 64); err == nil {
					tokensPerLine = v
				}
				if v, err := strconv.ParseFloat(parts[1], 64); err == nil {
					inputPerLine = v
				}
				if v, err := strconv.ParseFloat(parts[2], 64); err == nil {
					complexityWeight = v
				}
				if v, err := strconv.ParseFloat(parts[3], 64); err == nil {
					iterations = v
				}
				if v, err := strconv.ParseFloat(parts[4], 64); err == nil {
					iterationWeight = v
				}
			}
		}
		cycles := iterations
		if opts.LocomoCycles != nil {
			cycles = *opts.LocomoCycles
		} else {
			if total.Complexity > 0 {
				cycles = iterations + iterationWeight*math.Sqrt(float64(total.Complexity))/2.0
			}
		}
		baseMult := 1.5
		if total.Complexity > 0 {
			baseMult = 1 + math.Sqrt(float64(total.Complexity))/2.0
		}
		fullMult := baseMult
		if total.Complexity > 0 {
			fullMult = baseMult * (1 + complexityWeight*math.Sqrt(float64(total.Complexity))/2.0)
		}
		inputTokens := float64(total.Lines) * inputPerLine * fullMult
		outputTokens := float64(total.Lines) * tokensPerLine * baseMult
		costLLM := (inputTokens*inputPrice + outputTokens*outputPrice) / 1e6
		genSec := outputTokens / tps
		reviewMinutesPerLine := 0.01
		if opts.LocomoReview != nil {
			reviewMinutesPerLine = *opts.LocomoReview
		}
		reviewHours := float64(total.Lines) * reviewMinutesPerLine / 60.0
		j.EstimatedLLMCost = &costLLM
		j.EstimatedLLMInputTokens = &inputTokens
		j.EstimatedLLMOutputTokens = &outputTokens
		j.EstimatedLLMGenerationSeconds = &genSec
		j.EstimatedLLMReviewHours = &reviewHours
		j.EstimatedLLMPreset = &opts.LocomoPreset
		j.EstimatedLLMAverageComplexityMultiplier = &fullMult
		j.EstimatedLLMCycles = &cycles
	}
	data, _ := json.Marshal(j)
	return string(data)
}

