func parseLanguages(txt string) {
	extToLangs = make(map[string][]string)
	filenameToLang = make(map[string]string)
	lines := strings.Split(txt, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		// format: Name (exts)
		open := strings.LastIndex(line, "(")
		close := strings.LastIndex(line, ")")
		if open == -1 || close == -1 || close <= open {
			continue
		}
		name := strings.TrimSpace(line[:open])
		extsStr := line[open+1 : close]
		exts := strings.Split(extsStr, ",")
		var cleanExts []string
		for _, e := range exts {
			e = strings.TrimSpace(e)
			if e == "" {
				continue
			}
			cleanExts = append(cleanExts, e)
			low := strings.ToLower(e)
			// Decide if it's filename or extension:
			// If contains '.' or contains uppercase? Actually token may be like ".gitignore" or "Makefile" etc.
			// We'll store both as filename exact and extension.
			// For extension mapping, we use lower case ext without dot.
			// For filename mapping, we store lowercased base.
			if strings.Contains(e, ".") {
				// Could be filename like "CMakeLists.txt" or extension like "d.ts"? d.ts contains dot but is extension.
				// Heuristic: if starts with '.' it's filename like ".gitignore"
				// If contains '.' and length > 5 and not just like "d.ts", "blade.php", etc? Actually "blade.php" is extension with dot.
				// Let's treat all as possible filename and also extension token.
				// For filename mapping, store e lowercased.
				filenameToLang[low] = name
				// Also try to extract extension part after last dot for extension mapping?
				// For "blade.php", extension would be "php"? But original mapping shows Blade template (blade.php) - file "foo.blade.php" would be blade.php? Actually extension "blade.php" includes dot, so file "foo.blade.php" should match.
				// We'll handle matching logic later to check if filename ends with ".<ext>" case.
			} else {
				// no dot
				// If token is like "Makefile", "Dockerfile", etc (case-insensitive) we treat as filename too if it matches common filenames? Simpler treat all as both filename and extension candidate.
				// Check if token length > 4 and contains only letters? Could be filename like "Makefile" or "build" etc.
				// We'll store as filename if token length >=3 and not purely short extension? Let's store all as filename mapping as well for safety, but also as extension.
				filenameToLang[low] = name
			}
			extToLangs[low] = append(extToLangs[low], name)
		}
		langDefs = append(langDefs, LangDef{Name: name, Extensions: cleanExts})
	}
	// Additionally ensure some known filename mappings that were missed due to case sensitivity:
	// Makefile etc.
}

func isBinaryContent(content []byte) bool {
	// Implement heuristic deduced:
	// For each null byte position
	for i, b := range content {
		if b != 0 {
			continue
		}
		if i == 0 {
			continue
		}
		if i == len(content)-1 {
			continue
		}
		if content[i-1] == '\n' {
			continue
		}
		// Find line boundaries
		// Find previous newline
		prev := -1
		for j := i - 1; j >= 0; j-- {
			if content[j] == '\n' {
				prev = j
				break
			}
		}
		next := len(content)
		for j := i + 1; j < len(content); j++ {
			if content[j] == '\n' {
				next = j
				break
			}
		}
		line := content[prev+1 : next]
		// Check if line contains alphanumeric
		hasAlpha := false
		for _, c := range line {
			if c == 0 {
				continue
			}
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
				hasAlpha = true
				break
			}
		}
		if hasAlpha {
			return true
		}
	}
	return false
}

func detectLanguage(path string, content []byte, opts Options, countAsMap map[string]string, remapUnknown map[string]string, remapAll map[string]string) (string, []string) {
	base := filepath.Base(path)
	lowerBase := strings.ToLower(base)
	ext := ""
	if dot := strings.LastIndex(lowerBase, "."); dot != -1 {
		ext = lowerBase[dot+1:]
	}
	// count-as override
	if countAsMap != nil {
		if lang, ok := countAsMap[ext]; ok {
			return lang, []string{lang}
		}
		if lang, ok := countAsMap[lowerBase]; ok {
			return lang, []string{lang}
		}
		// also check full extension like "blade.php"
		for k, v := range countAsMap {
			if strings.HasSuffix(lowerBase, "."+k) || lowerBase == k {
				return v, []string{v}
			}
		}
	}

	// filename exact match
	if lang, ok := filenameToLang[lowerBase]; ok {
		// Possible languages: all langs that have this token
		possible := extToLangs[lowerBase]
		if len(possible) == 0 {
			possible = []string{lang}
		}
		// remap-all check
		if len(remapAll) > 0 {
			contentStr := string(content)
			for needle, newLang := range remapAll {
				if strings.Contains(contentStr, needle) {
					return newLang, possible
				}
			}
		}
		if len(remapUnknown) > 0 && len(possible) == 0 {
			contentStr := string(content)
			for needle, newLang := range remapUnknown {
				if strings.Contains(contentStr, needle) {
					return newLang, possible
				}
			}
		}
		return lang, possible
	}

	// check if base ends with .<ext> where ext contains dot (like blade.php)
	for token, lang := range filenameToLang {
		if strings.Contains(token, ".") {
			if strings.HasSuffix(lowerBase, "."+token) || strings.HasSuffix(lowerBase, token) {
				possible := extToLangs[token]
				return lang, possible
			}
		}
	}

	// extension match
	if ext != "" {
		if langs, ok := extToLangs[ext]; ok && len(langs) > 0 {
			primary := langs[0]
			// For json case, order in file: CloudFormation JSON before JSON, but we want JSON as primary for generic json. Our extToLangs for "json" will have both, first is CloudFormation JSON. But we want JSON as primary for generic. So we need to pick the last? Let's check: In languages.txt, CloudFormation JSON appears before JSON, so first is CloudFormation JSON, but observed primary for plain json file was JSON, not CloudFormation JSON. So they have logic to choose based on content? Or they pick the shortest name? Or they have priority: JSON is generic, CloudFormation is specific and only chosen if content contains "AWSTemplateFormatVersion" or something.
			// For simplicity, if multiple, choose the one that is not CloudFormation unless content indicates.
			// We'll implement: if len>1, look for known generic: "JSON", "YAML", etc? Let's try to pick the language whose name is shortest or whose name equals uppercase ext? For json, "JSON" vs "CloudFormation (JSON)" -> pick "JSON". So we can pick the language where name contains ext case-insensitive and is shortest, or where name == uppercased ext?
			// For json, ext "json", candidates ["CloudFormation (JSON)", "JSON"] -> pick "JSON" because length shorter.
			// Let's implement: choose shortest name.

			chosen := primary
			minLen := len(primary)
			for _, l := range langs {
				if len(l) < minLen {
					minLen = len(l)
					chosen = l
				}
			}
			// For remap
			contentStr := string(content)
			if len(remapAll) > 0 {
				for needle, newLang := range remapAll {
					if strings.Contains(contentStr, needle) {
						return newLang, langs
					}
				}
			}
			if len(remapUnknown) > 0 {
				// Only if unknown? But we have known, but for json generic case, we still want to check remap-unknown? Actually remap-unknown is for unknown types only.
				// For plain text case, we have unknown? Let's handle below.
			}
			// check remap for json content that might be CloudFormation?
			// If content contains "AWSTemplateFormatVersion" choose CloudFormation
			if strings.Contains(contentStr, "AWSTemplateFormatVersion") {
				for _, l := range langs {
					if strings.Contains(l, "CloudFormation") {
						return l, langs
					}
				}
			}
			return chosen, langs
		}
	}

	// Unknown: try shebang detection
	contentStr := string(content)
	if strings.HasPrefix(contentStr, "#!") {
		if strings.Contains(contentStr, "python") {
			return "Python", []string{"#!"}
		}
		if strings.Contains(contentStr, "bash") || strings.Contains(contentStr, "sh") {
			return "BASH", []string{"#!"}
		}
		if strings.Contains(contentStr, "ruby") {
			return "Ruby", []string{"#!"}
		}
		if strings.Contains(contentStr, "perl") {
			return "Perl", []string{"#!"}
		}
		if strings.Contains(contentStr, "node") {
			return "JavaScript", []string{"#!"}
		}
	}

	// remap-unknown check for unknown types
	if len(remapUnknown) > 0 {
		for needle, newLang := range remapUnknown {
			if strings.Contains(contentStr, needle) {
				return newLang, []string{"Plain Text"}
			}
		}
	}
	if len(remapAll) > 0 {
		for needle, newLang := range remapAll {
			if strings.Contains(contentStr, needle) {
				return newLang, []string{"Plain Text"}
			}
		}
	}

	// Fallback to Plain Text
	return "Plain Text", []string{"Plain Text"}
}

