func countFile(content []byte, lang string, noComplexity bool) CountResult {
	text := string(content)
	lines := strings.Split(text, "\n")
	// Handle last line without newline: strings.Split will give extra empty at end if ends with newline? Actually "a\n" split gives ["a",""] -> last empty should be counted? Original scc counts lines including last empty? Let's test: file with "a\n" gave Lines 1? Earlier test with file "package main\n" gave Lines 1, not 2. So they don't count trailing empty after final newline as blank. Our split gives extra empty, need to handle.
	// If content ends with newline, last element is empty, we should not count it as blank? Let's check: file "a\n" should be 1 line, not 2. So if last line empty and content ends with \n, ignore last.
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(text, "\n") {
		lines = lines[:len(lines)-1]
	}
	var res CountResult
	res.Lines = int64(len(lines))
	maxLen := 0
	totalLen := 0
	// For comment parsing, we need language-specific handling
	// We'll have configs per language
	// State for block comments
	inBlockComment := false
	blockStart := ""
	blockEnd := ""
	lineCommentTokens := []string{}
	// Determine comment syntax based on lang
	lowerLang := strings.ToLower(lang)
	switch lowerLang {
	case "go", "c", "c++", "c#", "java", "javascript", "typescript", "rust", "swift", "kotlin", "dart", "scala", "php", "csharp":
		lineCommentTokens = []string{"//"}
		blockStart = "/*"
		blockEnd = "*/"
	case "python":
		lineCommentTokens = []string{"#"}
		// Python block comments "'''" and '"""' handled separately
	case "bash", "sh", "shell", "zsh", "c shell", "fish", "korn shell", "bats":
		lineCommentTokens = []string{"#"}
	case "ruby", "perl", "yaml", "toml", "makefile", "dockerfile", "gitignore", "ignore", "docker ignore", "ini", "properties file":
		lineCommentTokens = []string{"#"}
	case "html", "xml", "xhtml":
		blockStart = "<!--"
		blockEnd = "-->"
	case "css", "scss", "less":
		blockStart = "/*"
		blockEnd = "*/"
	case "sql", "pl/sql":
		lineCommentTokens = []string{"--"}
		blockStart = "/*"
		blockEnd = "*/"
	case "lua":
		lineCommentTokens = []string{"--"}
	case "lisp", "clojure", "elixir", "scheme":
		lineCommentTokens = []string{";"}
	default:
		// Try generic: if lang contains "script" or unknown, use "#"
		if strings.Contains(lowerLang, "script") || strings.Contains(lowerLang, "bash") || strings.Contains(lowerLang, "shell") {
			lineCommentTokens = []string{"#"}
		} else if strings.Contains(lowerLang, "python") || strings.Contains(lowerLang, "ruby") || strings.Contains(lowerLang, "perl") {
			lineCommentTokens = []string{"#"}
		} else if strings.Contains(lowerLang, "html") || strings.Contains(lowerLang, "xml") {
			blockStart = "<!--"
			blockEnd = "-->"
		} else {
			// default C-style
			lineCommentTokens = []string{"//"}
			blockStart = "/*"
			blockEnd = "*/"
		}
	}

	// For complexity, define keywords per language
	var complexityKeywords []string
	var complexityOperators []string
	switch lowerLang {
	case "go":
		complexityKeywords = []string{"if", "for", "switch", "case", "default", "else", "go", "select"}
		complexityOperators = []string{"&&", "||"}
	case "c", "c++", "java", "c#", "javascript", "typescript", "rust", "kotlin", "swift", "php", "dart":
		complexityKeywords = []string{"if", "for", "while", "switch", "case", "else"}
		complexityOperators = []string{"&&", "||", "?"}
	case "python":
		complexityKeywords = []string{"if", "elif", "else", "for", "while", "except", "with", "and", "or", "case"}
		complexityOperators = []string{}
	case "bash", "sh", "shell":
		complexityKeywords = []string{"if", "for", "while", "case", "&&", "||"}
		complexityOperators = []string{"&&", "||"}
	default:
		complexityKeywords = []string{"if", "for", "switch", "case", "else", "&&", "||", "and", "or"}
		complexityOperators = []string{"&&", "||"}
	}

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		lineLen := len(line)
		if lineLen > maxLen {
			maxLen = lineLen
		}
		totalLen += lineLen

		if trimmed == "" {
			res.Blank++
			continue
		}

		// Block comment handling
		if inBlockComment {
			// Check if block end exists in line
			if blockEnd != "" && strings.Contains(line, blockEnd) {
				// Check if there's code after block end
				parts := strings.SplitN(line, blockEnd, 2)
				after := ""
				if len(parts) > 1 {
					after = strings.TrimSpace(parts[1])
				}
				// Check if there's code before block start? We are already inside block, so before is comment.
				// If after has code, count as code, else comment
				if after != "" {
					// Need to check if after is comment or code
					// Simple: if after starts with line comment token, then comment? but has code before? Actually after block end, if after is non-empty, it's code.
					// Unless after is only whitespace.
					// For simplicity, if after contains alphanumeric, count as code
					hasCodeAfter := false
					for _, c := range after {
						if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '"' || c == '\'' || c == '(' || c == ')' || c == '{' || c == '}' {
							hasCodeAfter = true
							break
						}
					}
					if hasCodeAfter {
						res.Code++
					} else {
						res.Comment++
					}
				} else {
					res.Comment++
				}
				// Check if block restarts in same line after end?
				inBlockComment = false
				// Continue but need to handle remaining line for complexity?
				// For complexity, we should count complexity in code part after block
				if !noComplexity && hasCodeAfterFunc(after) {
					// complexity counting for after part
					res.Complexity += countComplexity(after, complexityKeywords, complexityOperators, lowerLang)
				}
				// Also before part was comment, no complexity
			} else {
				res.Comment++
			}
			continue
		}

		// Check for block start
		if blockStart != "" && strings.Contains(line, blockStart) {
			// Find block start index
			startIdx := strings.Index(line, blockStart)
			endIdx := -1
			if blockEnd != "" {
				endIdx = strings.Index(line[startIdx+len(blockStart):], blockEnd)
			}
			before := strings.TrimSpace(line[:startIdx])
			after := ""
			hasCodeBefore := before != ""
			// If block ends on same line
			if endIdx != -1 {
				afterPart := line[startIdx+len(blockStart)+endIdx+len(blockEnd):]
				after = strings.TrimSpace(afterPart)
				hasCodeAfter := after != ""
				if hasCodeBefore || hasCodeAfter {
					res.Code++
				} else {
					res.Comment++
				}
				// complexity for before and after
				if !noComplexity {
					if hasCodeBefore {
						res.Complexity += countComplexity(line[:startIdx], complexityKeywords, complexityOperators, lowerLang)
					}
					if hasCodeAfter {
						res.Complexity += countComplexity(afterPart, complexityKeywords, complexityOperators, lowerLang)
					}
				}
			} else {
				// block continues to next lines
				if hasCodeBefore {
					res.Code++
					if !noComplexity {
						res.Complexity += countComplexity(line[:startIdx], complexityKeywords, complexityOperators, lowerLang)
					}
				} else {
					res.Comment++
				}
				inBlockComment = true
			}
			continue
		}

		// Check for Python triple quotes as block comments
		if lowerLang == "python" {
			trim := strings.TrimSpace(line)
			if strings.HasPrefix(trim, "\"\"\"") || strings.HasPrefix(trim, "'''") {
				// If single line triple quotes with closing on same line and no other code, comment? But our earlier test showed """ block """ counted as comment lines
				// We'll handle generally as comment if line starts with triple quotes
				if strings.HasPrefix(trim, "\"\"\"") {
					if strings.Count(line, "\"\"\"") >= 2 {
						// starts and ends on same line
						// Check if there's code besides triple quotes
						without := strings.ReplaceAll(line, "\"\"\"", "")
						if strings.TrimSpace(without) == "" {
							res.Comment++
						} else {
							res.Code++
							if !noComplexity {
								res.Complexity += countComplexity(without, complexityKeywords, complexityOperators, lowerLang)
							}
						}
					} else {
						// multiline start
						res.Comment++
						inBlockComment = true
						blockStart = "\"\"\""
						blockEnd = "\"\"\""
						// special handling: use same markers
					}
					continue
				}
				if strings.HasPrefix(trim, "'''") {
					if strings.Count(line, "'''") >= 2 {
						without := strings.ReplaceAll(line, "'''", "")
						if strings.TrimSpace(without) == "" {
							res.Comment++
						} else {
							res.Code++
							if !noComplexity {
								res.Complexity += countComplexity(without, complexityKeywords, complexityOperators, lowerLang)
							}
						}
					} else {
						res.Comment++
						inBlockComment = true
						blockStart = "'''"
						blockEnd = "'''"
					}
					continue
				}
			}
			// If inside triple-quoted block comment
			// Note: we reused inBlockComment for python triple quotes, but we need to differentiate marker
			// For simplicity, check if inBlockComment and blockStart is triple quote
			if inBlockComment && (blockStart == "\"\"\"" || blockStart == "'''") {
				if strings.Contains(line, blockEnd) {
					res.Comment++
					inBlockComment = false
					blockStart = ""
					blockEnd = ""
				} else {
					res.Comment++
				}
				continue
			}
		}

		// Line comment handling
		commentFound := false
		codePart := line
		for _, token := range lineCommentTokens {
			idx := strings.Index(line, token)
			if idx != -1 {
				// Check if token is inside string? For simplicity, check if before token there is a quote that is not closed.
				// We'll approximate: if token is "#" and file is Python/Bash, treat as comment only if not inside string.
				// For simplicity, if token is at beginning after trimming, it's comment.
				// Else, if token appears, we consider code before token as code.
				before := line[:idx]
				// Check if token is inside string: count quotes before idx
				// Simple check for " and ' : if odd number of quotes before, then inside string -> not comment
				if strings.Count(before, "\"")%2 == 1 || strings.Count(before, "'")%2 == 1 {
					// inside string, ignore
					continue
				}
				// Found comment token not inside string
				trimBefore := strings.TrimSpace(before)
				if trimBefore == "" {
					// Line starts with comment (maybe after spaces)
					res.Comment++
				} else {
					res.Code++
				}
				commentFound = true
				codePart = before
				break
			}
		}
		if commentFound {
			if !noComplexity {
				res.Complexity += countComplexity(codePart, complexityKeywords, complexityOperators, lowerLang)
			}
			continue
		}

		// No comment, it's code
		res.Code++
		if !noComplexity {
			res.Complexity += countComplexity(line, complexityKeywords, complexityOperators, lowerLang)
		}
	}

	if len(lines) > 0 {
		res.MeanLine = totalLen / len(lines)
	}
	res.MaxLine = maxLen

	return res
}

func hasCodeAfterFunc(s string) bool {
	return strings.TrimSpace(s) != ""
}

func countComplexity(code string, keywords []string, operators []string, lang string) int64 {
	// Simplified complexity counting:
	// For each keyword, count occurrences where keyword is surrounded by word boundaries and preceded by whitespace or start, and followed by space, '(', '{', ':' etc.
	// For operators &&, ||, require spaces around.
	count := int64(0)
	lowerCode := strings.ToLower(code) // for case-insensitive? Original seems case-sensitive for Go? if is lowercase, but we can be case-sensitive for Go, case-insensitive for Python? We'll be case-sensitive for simplicity but also check lower.

	// For Go, C, etc, keywords are lowercase, case-sensitive.
	// We'll search case-sensitive for Go, C, etc, but for Python case-sensitive as well.

	// Use regex-like manual search
	for _, kw := range keywords {
		if kw == "&&" || kw == "||" || kw == "??" || kw == "?" {
			continue
		}
		// Count occurrences
		idx := 0
		for {
			pos := strings.Index(code[idx:], kw)
			if pos == -1 {
				break
			}
			absPos := idx + pos
			// Check preceding char
			prevOK := false
			if absPos == 0 {
				prevOK = true
			} else {
				prevChar := code[absPos-1]
				if prevChar == ' ' || prevChar == '\t' || prevChar == '\n' || prevChar == '\r' || prevChar == '(' || prevChar == ';' {
					prevOK = true
				}
				// For Go, preceding must be whitespace only (not '('). But we allow '(' and ';' for Python etc.
				// We'll enforce whitespace for Go-like: if lang is go,c,java,js, then only whitespace
				if lang == "go" || lang == "c" || lang == "java" || lang == "javascript" {
					if prevChar == ' ' || prevChar == '\t' || prevChar == '\n' {
						prevOK = true
					} else {
						prevOK = false
					}
				}
			}
			// Check following char
			nextOK := false
			endPos := absPos + len(kw)
			if endPos >= len(code) {
				nextOK = true
			} else {
				nextChar := code[endPos]
				if nextChar == ' ' || nextChar == '\t' || nextChar == '\n' || nextChar == '(' || nextChar == '{' || nextChar == ':' || nextChar == ';' {
					nextOK = true
				}
				// For Go if, only space and '(' allowed
				if kw == "if" || kw == "for" || kw == "switch" {
					if nextChar == ' ' || nextChar == '(' {
						nextOK = true
					} else if kw == "for" && nextChar == '{' {
						nextOK = true
					} else if kw == "switch" && (nextChar == ' ' || nextChar == '(' || nextChar == '{') {
						nextOK = true
					} else {
						nextOK = false
					}
					// tab not allowed per earlier observations
					if nextChar == '\t' {
						nextOK = false
					}
				}
				// For else, allow space and '{'
				if kw == "else" {
					if nextChar == ' ' || nextChar == '{' || nextChar == '\t' || nextChar == '\n' {
						nextOK = true
					}
				}
			}
			if prevOK && nextOK {
				// Also ensure not part of longer identifier: check preceding and following are not alphanumeric or underscore
				if absPos > 0 {
					pc := code[absPos-1]
					if (pc >= 'a' && pc <= 'z') || (pc >= 'A' && pc <= 'Z') || (pc >= '0' && pc <= '9') || pc == '_' {
						// part of identifier, skip
						idx = absPos + len(kw)
						continue
					}
				}
				if endPos < len(code) {
					nc := code[endPos]
					if (nc >= 'a' && nc <= 'z') || (nc >= 'A' && nc <= 'Z') || (nc >= '0' && nc <= '9') || nc == '_' {
						idx = absPos + len(kw)
						continue
					}
				}
				count++
			}
			idx = absPos + len(kw)
		}
	}

	// Operators
	for _, op := range operators {
		// Search for " op " with spaces
		idx := 0
		for {
			pos := strings.Index(code[idx:], op)
			if pos == -1 {
				break
			}
			absPos := idx + pos
			// Check surrounding spaces
			prevOK := false
			nextOK := false
			if absPos > 0 {
				if code[absPos-1] == ' ' || code[absPos-1] == '\t' {
					prevOK = true
				}
			}
			if absPos+len(op) < len(code) {
				if code[absPos+len(op)] == ' ' || code[absPos+len(op)] == '\t' {
					nextOK = true
				}
			}
			if prevOK && nextOK {
				count++
			} else {
				// For && and ||, also count if preceded/followed by space but not necessarily both? Our earlier observations required both spaces.
				// We'll require both
			}
			idx = absPos + len(op)
		}
	}

	// Special handling for Python "and" "or" already counted as keywords with spaces, but we want to ensure they are counted as complexity.
	// The keyword counting above for "and" will count if surrounded by spaces.

	return count
}

