func percent(part, total int64) string {
	if total == 0 {
		return "NaN%"
	}
	p := float64(part) / float64(total) * 100.0
	return fmt.Sprintf("%.1f%%", p)
}

func computeCOCOMOWithEffort(codeLines int64, opts Options) (float64, float64, float64, float64) {
	kloc := float64(codeLines) / 1000.0
	var a, b, c, d float64
	switch strings.ToLower(opts.CocomoType) {
	case "semi-detached":
		a = 3.0
		b = 1.12
		c = 2.5
		d = 0.35
	case "embedded":
		a = 3.6
		b = 1.20
		c = 2.5
		d = 0.32
	default:
		if strings.HasPrefix(strings.ToLower(opts.CocomoType), "custom") {
			parts := strings.Split(opts.CocomoType, ",")
			if len(parts) == 5 {
				a, _ = strconv.ParseFloat(parts[1], 64)
				b, _ = strconv.ParseFloat(parts[2], 64)
				c, _ = strconv.ParseFloat(parts[3], 64)
				d, _ = strconv.ParseFloat(parts[4], 64)
			} else {
				a = 2.4
				b = 1.05
				c = 2.5
				d = 0.38
			}
		} else {
			a = 2.4
			b = 1.05
			c = 2.5
			d = 0.38
		}
	}
	effort := a * math.Pow(kloc, b) * opts.EAF
	schedule := c * math.Pow(effort, d)
	people := 0.0
	if schedule != 0 {
		people = effort / schedule
	}
	cost := effort / 12.0 * float64(opts.AvgWage) * opts.Overhead
	return effort, schedule, people, cost
}

func formatLOCOMO(total LangSummary, opts Options) string {
	// Simplified LOCOMO: compute tokens etc.
	// Use preset to get prices and tps
	var inputPrice, outputPrice float64
	var tps float64
	switch strings.ToLower(opts.LocomoPreset) {
	case "small":
		inputPrice = 0.5
		outputPrice = 2
		tps = 100
	case "large":
		inputPrice = 10
		outputPrice = 30
		tps = 30
	case "local":
		inputPrice = 0
		outputPrice = 0
		tps = 15
	case "medium":
		fallthrough
	default:
		inputPrice = 3
		outputPrice = 15
		tps = 50
	}
	if opts.LocomoInputPrice != nil {
		inputPrice = *opts.LocomoInputPrice
	}
	if opts.LocomoOutputPrice != nil {
		outputPrice = *opts.LocomoOutputPrice
	}
	if opts.LocomoTps != nil {
		tps = *opts.LocomoTps
	}
	// tokens per line etc from config
	tokensPerLine := 15.0
	inputPerLine := 30.0
	complexityWeight := 2.0
	iterations := 1.5
	iterationWeight := 2.0
	if opts.LocomoConfig != "" {
		parts := strings.Split(opts.LocomoConfig, ",")
		if len(parts) == 5 {
			if v, err := strconv.ParseFloat(parts[0], 64); err == nil {
				tokensPerLine = v
			}
			if v, err := strconv.ParseFloat(parts[1], 64); err == nil {
				inputPerLine = v
			}
			if v, err := strconv.ParseFloat(parts[2], 64); err == nil {
				complexityWeight = v
			}
			if v, err := strconv.ParseFloat(parts[3], 64); err == nil {
				iterations = v
			}
			if v, err := strconv.ParseFloat(parts[4], 64); err == nil {
				iterationWeight = v
			}
		}
	}
	// Override cycles if specified
	cycles := iterations
	if opts.LocomoCycles != nil {
		cycles = *opts.LocomoCycles
	} else {
		// Calculate cycles based on complexity: cycles = iterations + iterationWeight * sqrt(complexity)/2
		// Complexity is total complexity
		if total.Complexity > 0 {
			cycles = iterations + iterationWeight*math.Sqrt(float64(total.Complexity))/2.0
		}
	}
	// Average complexity multiplier
	// For complexity 0, mult =1.5? Actually earlier for medium preset with complexity0 mult=1.5, with complexity>0 mult larger.
	// Using formula: baseMult = 1 + sqrt(C)/2
	// fullMult = baseMult * (1 + complexityWeight * sqrt(C)/2)
	baseMult := 1.0
	if total.Complexity > 0 {
		baseMult = 1 + math.Sqrt(float64(total.Complexity))/2.0
	} else {
		// For medium preset, baseMult is 1.5 even for C=0? In our data, for C0 mult was 1.5 for medium. So maybe baseMult for preset includes 1.5?
		// For simplicity, if C==0, set baseMult=1.5 for medium, else baseMult as above? Actually for custom config with weight0 C0 mult=1, but for medium C0 mult=1.5. So medium has extra 0.5.
		// We'll set baseMult for C0 as 1.5 if preset medium, else 1?
		// For simplicity, we'll set baseMult for C0 as 1.5 for all presets? Check small preset C0 mult was 1.5 as well? Earlier small preset for 1 line file mult was 1.5 as well (from earlier output small preset for 1 line had cycles 1.5 but mult? We didn't check mult for small preset C0. Let's assume 1.5 base for all.

		baseMult = 1.5
	}
	fullMult := baseMult
	if total.Complexity > 0 {
		fullMult = baseMult * (1 + complexityWeight*math.Sqrt(float64(total.Complexity))/2.0)
	}

	inputTokens := float64(total.Lines) * inputPerLine * fullMult
	outputTokens := float64(total.Lines) * tokensPerLine * baseMult

	cost := (inputTokens*inputPrice + outputTokens*outputPrice) / 1e6

	genSeconds := outputTokens / tps
	// Generation time serial: genSeconds * cycles? Or genSeconds alone? Earlier we found genSeconds = outputTokens / tps (without cycles). Let's see: for complexity2, output 159, tps 50, genSec 3.18? Actually earlier for 6 lines complexity2, output 159, genSec 3.18, tps 50 => 159/50=3.18 matches genSec alone, no cycles. So genSec = outputTokens / tps
	// But earlier for 100 lines output1500 genSec 30 =>1500/50=30 matches.

	reviewMinutesPerLine := 0.01
	if opts.LocomoReview != nil {
		reviewMinutesPerLine = *opts.LocomoReview
	}
	reviewHours := float64(total.Lines) * reviewMinutesPerLine / 60.0

	// Format output
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", opts.LocomoPreset))
	sb.WriteString(fmt.Sprintf("  Tokens Required (in/out) %.1fM / %.1fM\n", inputTokens/1e6, outputTokens/1e6))
	sb.WriteString(fmt.Sprintf("  Cost to Generate $%g\n", cost))
	sb.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", cycles))
	sb.WriteString(fmt.Sprintf("  Generation Time (serial) %.1f minutes\n", genSeconds/60.0))
	sb.WriteString(fmt.Sprintf("  Human Review Time %.1f hours\n", reviewHours))
	sb.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
	sb.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
	return sb.String()
}

