func formatSQL(summaries []LangSummary, cost, schedule, people float64, opts Options, insertOnly bool) string {
	var sb strings.Builder
	project := opts.SQLProject
	if project == "" {
		// Use first path or something
		project = "."
	}
	if !insertOnly {
		sb.WriteString(fmt.Sprintf("create table metadata (   -- github.com/boyter/scc v %s\n", version))
		sb.WriteString("             timestamp text,\n")
		sb.WriteString("             Project   text,\n")
		sb.WriteString("             elapsed_s real,\n")
		sb.WriteString("             estimated_cost real,\n")
		sb.WriteString("             estimated_schedule_months real,\n")
		sb.WriteString("             estimated_people real);\n")
		sb.WriteString("create table t        (\n")
		sb.WriteString("             Project       text   ,\n")
		sb.WriteString("             Language      text   ,\n")
		sb.WriteString("             File          text   ,\n")
		sb.WriteString("             File_dirname  text   ,\n")
		sb.WriteString("             File_basename text   ,\n")
		sb.WriteString("             nByte         integer,\n")
		sb.WriteString("             nBlank        integer,\n")
		sb.WriteString("             nComment      integer,\n")
		sb.WriteString("             nCode         integer,\n")
		sb.WriteString("             nComplexity   integer,\n")
		sb.WriteString("             nUloc         integer    \n")
		sb.WriteString(");\n")
	}
	sb.WriteString("begin transaction;\n")
	for _, s := range summaries {
		if opts.ByFile && len(s.Files) > 0 {
			for _, f := range s.Files {
				dir := filepath.Dir(f.Location) + "/"
				sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n", project, s.Name, f.Location, dir, f.Filename, f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
			}
		} else {
			// For non-by-file, we need to output per file? Original sql without by-file still outputs per file? In earlier test, without by-file, sql output had per file inserts for each file in directory.
			// Our summaries without Files have no file list, so we would output nothing. To match original, we need to output per file even when not by-file for sql format? Let's check earlier: for /tmp/testproj without by-file, sql format gave inserts for each file: it had 2 inserts for main.go and a.js. So even without by-file, sql outputs per file.

			// For our implementation, if Files empty, we can output one row per language aggregated? But original outputs per file. So we need to handle same as by-file for sql.

			// As fallback, if no Files, output one row with empty file? But better to output per file if we have them? We cleared Files when not by-file, but for sql we should keep them. For simplicity, if Files empty, we output a row for the language with file = ""? Let's check original behavior for sql without by-file: it still had file paths. So they must have file list even without by-file. So for sql format, we should always output per file.

			// For our MVP, if Files empty, we will not output anything for that language, which would be wrong. So we need to ensure for sql format we have file list. We'll handle by using a global allFiles variable? But we don't have it here.

			// For now, we'll output per summary if no files: with empty file field
			if len(s.Files) == 0 {
				sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '', '', '', %d, %d, %d, %d, %d, %d);\n", project, s.Name, s.Bytes, s.Blank, s.Comment, s.Code, s.Complexity, s.ULOC))
			}
		}
	}
	sb.WriteString("commit;\n")
	sb.WriteString("begin transaction;\n")
	now := time.Now().Format("2006-01-02 15:04:05")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', %.6f, %f, %f, %f);\n", now, project, 0.001, cost, schedule, people))
	sb.WriteString("commit;")
	return sb.String()
}

