				}
				opts.NotMatch = append(opts.NotMatch, val)
			case "--output":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.Output = val
			case "--overhead":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				if f, err := strconv.ParseFloat(val, 64); err == nil {
					opts.Overhead = f
				}
			case "--percent":
				opts.Percent = true
			case "--remap-all":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.RemapAll = val
				re := regexp.MustCompile(`"(.*?)":"(.*?)"`)
				matches := re.FindAllStringSubmatch(val, -1)
				for _, m := range matches {
					if len(m) == 3 {
						remapAll[m[1]] = m[2]
					}
				}
			case "--remap-unknown":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.RemapUnknown = val
				re := regexp.MustCompile(`"(.*?)":"(.*?)"`)
				matches := re.FindAllStringSubmatch(val, -1)
				for _, m := range matches {
					if len(m) == 3 {
						remapUnknown[m[1]] = m[2]
					}
				}
			case "--size-unit":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.SizeUnit = val
			case "--sloccount-format":
				opts.SloccountFormat = true
			case "--sort":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.Sort = val
			case "--sql-project":
				if val == "" {
					i++
					if i < len(args) {
						val = args[i]
					}
				}
				opts.SQLProject = val
			case "--trace":
				opts.Trace = true
			case "--uloc":
				opts.Uloc = true
			case "--verbose":
				opts.Verbose = true
			case "--wide":
				opts.Wide = true
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			switch arg {
			case "-m":
				opts.Character = true
			case "-a":
				opts.Dryness = true
				opts.Uloc = true
			case "-x":
				i++
				if i < len(args) {
					val := args[i]
					opts.ExcludeExt = append(opts.ExcludeExt, strings.Split(val, ",")...)
				}
			case "-n":
				i++
				if i < len(args) {
					val := args[i]
					opts.ExcludeFile = append(opts.ExcludeFile, strings.Split(val, ",")...)
				}
			case "-f":
				i++
				if i < len(args) {
					opts.Format = args[i]
				}
			case "-z":
				opts.MinGen = true
			case "-c":
				opts.NoComplexity = true
			case "-d":
				opts.NoDuplicates = true
			case "-M":
				i++
				if i < len(args) {
					opts.NotMatch = append(opts.NotMatch, args[i])
				}
			case "-o":
				i++
				if i < len(args) {
					opts.Output = args[i]
				}
			case "-p":
				opts.Percent = true
			case "-s":
				i++
				if i < len(args) {
					opts.Sort = args[i]
				}
			case "-t":
				opts.Trace = true
			case "-u":
				opts.Uloc = true
			case "-v":
				opts.Verbose = true
			case "-w":
				opts.Wide = true
			case "-l":
				fmt.Print(languagesText)
				if !strings.HasSuffix(languagesText, "\n") {
					fmt.Println()
				}
				return
			case "-h":
				fmt.Print(helpText)
				return
			case "-i":
				i++
				if i < len(args) {
					val := args[i]
					opts.IncludeExt = append(opts.IncludeExt, strings.Split(val, ",")...)
				}
			default:
				// combined short flags
				chars := arg[1:]
				for _, ch := range chars {
					switch ch {
					case 'm':
						opts.Character = true
					case 'a':
						opts.Dryness = true
						opts.Uloc = true
					case 'c':
						opts.NoComplexity = true
					case 'd':
						opts.NoDuplicates = true
					case 'p':
						opts.Percent = true
					case 't':
						opts.Trace = true
					case 'u':
						opts.Uloc = true
					case 'v':
						opts.Verbose = true
					case 'w':
						opts.Wide = true
					case 'l':
						fmt.Print(languagesText)
						if !strings.HasSuffix(languagesText, "\n") {
							fmt.Println()
						}
						return
					case 'h':
						fmt.Print(helpText)
						return
					}
				}
			}
		} else {
			paths = append(paths, arg)
		}
		i++
	}
	if opts.MCP {
		return
	}
	if len(paths) == 0 {
		paths = []string{"."}
	}
	allFiles := []FileStat{}
	seenHashes := make(map[string]bool)
	for _, root := range paths {
		info, err := os.Lstat(root)
		if err != nil {
			continue
		}
		if !info.IsDir() {
			if info.Mode()&fs.ModeSymlink != 0 && !opts.IncludeSymlinks {
				continue
			}
			if shouldExcludeFile(root, nil, opts) {
				continue
			}
			stat, ok := processFile(root, root, opts, countAsMap, remapUnknown, remapAll, seenHashes)
			if ok {
				allFiles = append(allFiles, stat)
			}
		} else {
			filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					base := d.Name()
					for _, ex := range opts.ExcludeDir {
						if strings.ToLower(base) == strings.ToLower(ex) {
							return fs.SkipDir
						}
					}
					for _, pattern := range opts.NotMatch {
						matched, _ := regexp.MatchString(pattern, p)
						if matched {
							return fs.SkipDir
						}
					}
					return nil
				}
				if d.Type()&fs.ModeSymlink != 0 && !opts.IncludeSymlinks {
					return nil
				}
				if shouldExcludeFile(p, nil, opts) {
					return nil
				}
				stat, ok := processFile(p, root, opts, countAsMap, remapUnknown, remapAll, seenHashes)
				if ok {
					allFiles = append(allFiles, stat)
				}
				return nil
			})
		}
	}
	langMap := make(map[string]*LangSummary)
	for _, f := range allFiles {
		langName := f.Language
		if f.Minified {
			if opts.NoMin || opts.NoMinGen {
				continue
			}
			if opts.Min || opts.MinGen {
				if !strings.HasSuffix(langName, " (min)") {
					langName = f.Language + " (min)"
				}
			}
		}
		if f.Generated {
			if opts.NoGen || opts.NoMinGen {
				continue
			}
			if opts.Gen || opts.MinGen {
				if !strings.HasSuffix(langName, " (gen)") {
					langName = f.Language + " (gen)"
				}
			}
		}
		if opts.NoLarge {
			if f.Bytes > int64(opts.LargeByteCount) || f.Lines > int64(opts.LargeLineCount) {
				continue
			}
		}
		if _, ok := langMap[langName]; !ok {
			langMap[langName] = &LangSummary{Name: langName}
		}
		ls := langMap[langName]
		ls.Bytes += f.Bytes
		ls.Lines += f.Lines
		ls.Code += f.Code
		ls.Comment += f.Comment
		ls.Blank += f.Blank
		ls.Complexity += f.Complexity
		ls.Count++
		if opts.ByFile {
			ls.Files = append(ls.Files, f)
		}
	}
	var summaries []LangSummary
	for _, v := range langMap {
		if !opts.ByFile {
			v.Files = []FileStat{}
		}
		summaries = append(summaries, *v)
	}
	sort.Slice(summaries, func(i, j int) bool {
		switch strings.ToLower(opts.Sort) {
		case "name":
			return strings.ToLower(summaries[i].Name) < strings.ToLower(summaries[j].Name)
		case "lines":
			return summaries[i].Lines > summaries[j].Lines
		case "blanks":
			return summaries[i].Blank > summaries[j].Blank
		case "code":
			return summaries[i].Code > summaries[j].Code
		case "comments":
			return summaries[i].Comment > summaries[j].Comment
		case "complexity":
			return summaries[i].Complexity > summaries[j].Complexity
		default:
			if summaries[i].Count != summaries[j].Count {
				return summaries[i].Count > summaries[j].Count
			}
			return strings.ToLower(summaries[i].Name) < strings.ToLower(summaries[j].Name)
		}
	})
	if opts.ByFile {
		for idx := range summaries {
			sort.Slice(summaries[idx].Files, func(a, b int) bool {
				switch strings.ToLower(opts.Sort) {
				case "name":
					return summaries[idx].Files[a].Filename < summaries[idx].Files[b].Filename
				case "lines":
					return summaries[idx].Files[a].Lines > summaries[idx].Files[b].Lines
				case "code":
					return summaries[idx].Files[a].Code > summaries[idx].Files[b].Code
				default:
					return summaries[idx].Files[a].Filename < summaries[idx].Files[b].Filename
				}
			})
		}
	}
	var total LangSummary
	total.Name = "Total"
	for _, s := range summaries {
		total.Bytes += s.Bytes
		total.Lines += s.Lines
		total.Code += s.Code
		total.Comment += s.Comment
		total.Blank += s.Blank
		total.Complexity += s.Complexity
		total.Count += s.Count
	}
	cost, schedule, people := computeCOCOMO(total.Code, opts)
	if opts.Uloc || opts.Dryness {
		for i := range summaries {
			summaries[i].ULOC = summaries[i].Code
		}
		total.ULOC = total.Code
	}
	output := ""
	switch strings.ToLower(opts.Format) {
	case "json":
		output = formatJSON(summaries, opts)
	case "json2":
		output = formatJSON2(summaries, cost, schedule, people, opts)
	case "csv":
		output = formatCSV(summaries, opts)
	case "csv-stream":
		output = formatCSVStream(allFiles, summaries, opts)
	case "cloc-yaml":
		output = formatClocYAML(summaries, opts)
	case "html":
		output = formatHTML(summaries, cost, schedule, people, opts, false)
	case "html-table":
		output = formatHTML(summaries, cost, schedule, people, opts, true)
	case "sql":
		output = formatSQL(allFiles, summaries, cost, schedule, people, opts, false)
	case "sql-insert":
		output = formatSQL(allFiles, summaries, cost, schedule, people, opts, true)
	case "openmetrics":
		output = formatOpenMetrics(summaries, opts)
	case "wide":
		output = formatTabular(summaries, total, cost, schedule, people, opts, true)
	default:
		output = formatTabular(summaries, total, cost, schedule, people, opts, false)
	}
	if opts.FormatMulti != "" {
		pairs := strings.Split(opts.FormatMulti, ",")
		for _, p := range pairs {
			parts := strings.SplitN(strings.TrimSpace(p), ":", 2)
			if len(parts) != 2 {
				continue
			}
			fm := strings.TrimSpace(parts[0])
			dest := strings.TrimSpace(parts[1])
			var out string
			switch strings.ToLower(fm) {
			case "json":
				out = formatJSON(summaries, opts)
			case "json2":
				out = formatJSON2(summaries, cost, schedule, people, opts)
			case "csv":
				out = formatCSV(summaries, opts)
			case "csv-stream":
				out = formatCSVStream(allFiles, summaries, opts)
			case "cloc-yaml":
				out = formatClocYAML(summaries, opts)
			case "html":
				out = formatHTML(summaries, cost, schedule, people, opts, false)
			case "html-table":
				out = formatHTML(summaries, cost, schedule, people, opts, true)
			case "sql":
				out = formatSQL(allFiles, summaries, cost, schedule, people, opts, false)
			case "sql-insert":
				out = formatSQL(allFiles, summaries, cost, schedule, people, opts, true)
			case "openmetrics":
				out = formatOpenMetrics(summaries, opts)
			case "wide":
				out = formatTabular(summaries, total, cost, schedule, people, opts, true)
			default:
				out = formatTabular(summaries, total, cost, schedule, people, opts, false)
			}
			if dest == "stdout" {
				fmt.Print(out)
			} else {
				os.WriteFile(dest, []byte(out), 0644)
			}
		}
		return
	}
	if opts.Output != "" && opts.Output != "stdout" {
		os.WriteFile(opts.Output, []byte(output), 0644)
		return
	}
	fmt.Print(output)
}

func shouldExcludeFile(path string, info fs.FileInfo, opts Options) bool {
	base := filepath.Base(path)
	lowerBase := strings.ToLower(base)
	for _, ef := range opts.ExcludeFile {
		ef = strings.TrimSpace(ef)
		if ef == "" {
			continue
		}
		if matched, _ := filepath.Match(strings.ToLower(ef), lowerBase); matched {
			return true
		}
		if lowerBase == strings.ToLower(ef) {
			return true
		}
	}
	ext := ""
	if dot := strings.LastIndex(lowerBase, "."); dot != -1 {
		ext = lowerBase[dot+1:]
	}
	for _, ex := range opts.ExcludeExt {
		ex = strings.TrimSpace(strings.ToLower(ex))
		if ex == "" {
			continue
		}
		if ext == ex {
			return true
		}
	}
	if len(opts.IncludeExt) > 0 {
		found := false
		for _, inc := range opts.IncludeExt {
			inc = strings.TrimSpace(strings.ToLower(inc))
			if inc == "" {
				continue
			}
			if ext == inc {
				found = true
				break
			}
			if lowerBase == inc {
				found = true
				break
			}
		}
		if !found {
			return true
		}
	}
	for _, pattern := range opts.NotMatch {
		if pattern == "" {
			continue
		}
		matched, _ := regexp.MatchString(pattern, path)
		if matched {
			return true
		}
		matchedBase, _ := regexp.MatchString(pattern, base)
		if matchedBase {
			return true
		}
	}
	return false
}

func processFile(path string, root string, opts Options, countAsMap map[string]string, remapUnknown map[string]string, remapAll map[string]string, seenHashes map[string]bool) (FileStat, bool) {
	content, err := os.ReadFile(path)
	if err != nil {
		return FileStat{}, false
	}
	bytesCount := int64(len(content))
	if !opts.Binary {
		if isBinaryContent(content) {
			return FileStat{}, false
		}
	}
	linesCount := int64(strings.Count(string(content), "\n"))
	if len(content) > 0 && !strings.HasSuffix(string(content), "\n") {
		linesCount++
	}
	if opts.NoLarge {
		if bytesCount > int64(opts.LargeByteCount) || linesCount > int64(opts.LargeLineCount) {
			return FileStat{}, false
		}
	}
	lang, possible := detectLanguage(path, content, opts, countAsMap, remapUnknown, remapAll)
	isGen := false
	if len(content) > 0 {
		head := string(content)
		if len(head) > 1000 {
			head = head[:1000]
		}
		lowerHead := strings.ToLower(head)
		for _, marker := range opts.GeneratedMarkers {
			if strings.Contains(lowerHead, strings.ToLower(marker)) {
				isGen = true
				break
			}
		}
	}
	isMin := false
	if linesCount > 0 {
		avg := float64(bytesCount) / float64(linesCount)
		if avg > float64(opts.MinGenLineLength) {
			isMin = true
		}
	}
	if opts.NoDuplicates {
		hash := sha256.Sum256(content)
		hs := fmt.Sprintf("%x", hash)
		if seenHashes[hs] {
			return FileStat{}, false
		}
		seenHashes[hs] = true
	}
	countRes := countFile(content, lang, opts.NoComplexity)
	base := filepath.Base(path)
	ext := filepath.Ext(base)
	if ext != "" {
		ext = ext[1:]
	} else {
		ext = base
	}
	lowerBase := strings.ToLower(base)
	if lowerBase == ".gitignore" || lowerBase == ".ignore" {
		if !opts.CountIgnore {
			return FileStat{}, false
		}
	}
	stat := FileStat{
		Language:          lang,
		PossibleLanguages: possible,
		Filename:          base,
		Extension:         ext,
		Location:          path,
		Bytes:             bytesCount,
		Lines:             countRes.Lines,
		Code:              countRes.Code,
		Comment:           countRes.Comment,
		Blank:             countRes.Blank,
		Complexity:        countRes.Complexity,
		Binary:            false,
		Minified:          isMin,
		Generated:         isGen,
	}
	if opts.Uloc || opts.Dryness {
		stat.Uloc = countRes.Code
	}
	return stat, true
}

func computeCOCOMO(codeLines int64, opts Options) (float64, float64, float64) {
	kloc := float64(codeLines) / 1000.0
	var a, b, c, d float64
	switch strings.ToLower(opts.CocomoType) {
	case "semi-detached":
		a = 3.0
		b = 1.12
		c = 2.5
		d = 0.35
	case "embedded":
		a = 3.6
		b = 1.20
		c = 2.5
		d = 0.32
	default:
		if strings.HasPrefix(strings.ToLower(opts.CocomoType), "custom") {
			parts := strings.Split(opts.CocomoType, ",")
			if len(parts) == 5 {
				a, _ = strconv.ParseFloat(parts[1], 64)
				b, _ = strconv.ParseFloat(parts[2], 64)
				c, _ = strconv.ParseFloat(parts[3], 64)
				d, _ = strconv.ParseFloat(parts[4], 64)
			} else {
				a = 2.4
				b = 1.05
				c = 2.5
				d = 0.38
			}
		} else {
			a = 2.4
			b = 1.05
			c = 2.5
			d = 0.38
		}
	}
	effort := a * math.Pow(kloc, b) * opts.EAF
	schedule := c * math.Pow(effort, d)
	people := 0.0
	if schedule != 0 {
		people = effort / schedule
	}
	cost := effort / 12.0 * float64(opts.AvgWage) * opts.Overhead
	return cost, schedule, people
}

func formatSize(bytes int64, unit string) string {
	switch strings.ToLower(unit) {
	case "binary":
		mb := float64(bytes) / (1024 * 1024)
		return fmt.Sprintf("%d bytes, %.3f megabytes (BINARY)", bytes, mb)
	case "mixed":
		mb := float64(bytes) / (1024.0 * 1000.0)
		return fmt.Sprintf("%d bytes, %.3f megabytes (MIXED)", bytes, mb)
	case "si":
		fallthrough
	default:
		mb := float64(bytes) / 1000000.0
		return fmt.Sprintf("%d bytes, %.3f megabytes (SI)", bytes, mb)
	}
}

func formatTabular(summaries []LangSummary, total LangSummary, cost, schedule, people float64, opts Options, wide bool) string {
	var sb strings.Builder
	borderChar := "─"
	if opts.CI {
		borderChar = "-"
	}
	borderLen := 79
	if wide {
		borderLen = 141
	}
	printBorder := func() {
		if !opts.NoHborder {
			sb.WriteString(strings.Repeat(borderChar, borderLen) + "\n")
		}
	}
	printBorder()
	if wide {
		sb.WriteString("Language                              Files     Lines   Blanks  Comments     Code Complexity Complexity/Lines\n")
	} else {
		sb.WriteString("Language            Files       Lines    Blanks  Comments       Code Complexity\n")
	}
	printBorder()
	for _, s := range summaries {
		if wide {
			cpl := 0.0
			if s.Lines > 0 {
				cpl = float64(s.Complexity) / float64(s.Lines)
			}
			sb.WriteString(fmt.Sprintf("%-30s %9d %9d %8d %9d %8d %10d %17.2f\n", s.Name, s.Count, s.Lines, s.Blank, s.Comment, s.Code, s.Complexity, cpl))
			if opts.ByFile {
				for _, f := range s.Files {
					sb.WriteString(fmt.Sprintf("%-30s %9d %8d %9d %8d %10d %17.2f\n", f.Location, f.Lines, f.Blank, f.Comment, f.Code, f.Complexity, cpl))
				}
			}
		} else {
			sb.WriteString(fmt.Sprintf("%-19s %9d %11d %10d %10d %11d %10d\n", s.Name, s.Count, s.Lines, s.Blank, s.Comment, s.Code, s.Complexity))
			if opts.ByFile {
				for _, f := range s.Files {
					sb.WriteString(fmt.Sprintf("%-40s %11d %10d %10d %11d %10d\n", f.Location, f.Lines, f.Blank, f.Comment, f.Code, f.Complexity))
				}
			}
		}
	}
	printBorder()
	if wide {
		cpl := 0.0
		if total.Lines > 0 {
			cpl = float64(total.Complexity) / float64(total.Lines)
		}
		sb.WriteString(fmt.Sprintf("%-30s %9d %9d %8d %9d %8d %10d %17.2f\n", "Total", total.Count, total.Lines, total.Blank, total.Comment, total.Code, total.Complexity, cpl))
	} else {
		sb.WriteString(fmt.Sprintf("%-19s %9d %11d %10d %10d %11d %10d\n", "Total", total.Count, total.Lines, total.Blank, total.Comment, total.Code, total.Complexity))
	}
	printBorder()
	if !opts.NoCocomo {
		if opts.SloccountFormat {
			kloc := float64(total.Code) / 1000.0
			effortMonths := 2.4 * math.Pow(kloc, 1.05) * opts.EAF
			sb.WriteString(fmt.Sprintf("Total Physical Source Lines of Code (SLOC)                     = %d\n", total.Code))
			sb.WriteString(fmt.Sprintf("Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n", effortMonths/12.0, effortMonths))
			sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Person-Months = 2.40*(KSLOC**1.05)*%.2f)\n", opts.EAF))
			sb.WriteString(fmt.Sprintf("Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n", schedule/12.0, schedule))
			sb.WriteString(" (Basic COCOMO model, Months = 2.50*(person-months**0.38))\n")
			sb.WriteString(fmt.Sprintf("Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n", people))
			sb.WriteString(fmt.Sprintf("Total Estimated Cost to Develop                                = %s%.0f\n", opts.CurrencySymbol, cost))
			sb.WriteString(fmt.Sprintf(" (average salary = $%d/year, overhead = %.2f)\n", opts.AvgWage, opts.Overhead))
		} else {
			sb.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%.0f\n", opts.CocomoType, opts.CurrencySymbol, cost))
			sb.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", opts.CocomoType, schedule))
			sb.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", opts.CocomoType, people))
		}
		if opts.Locomo {
			sb.WriteString(formatLOCOMO(total, opts))
		}
		printBorder()
	} else {
		if opts.Locomo {
			sb.WriteString(formatLOCOMO(total, opts))
			printBorder()
		}
	}
	if !opts.NoSize {
		sb.WriteString("Processed " + formatSize(total.Bytes, opts.SizeUnit) + "\n")
		printBorder()
	}
	return sb.String()
}

func percent(part, total int64) string {
	if total == 0 {
		return "NaN%"
	}
	return fmt.Sprintf("%.1f%%", float64(part)/float64(total)*100)
}

func formatLOCOMO(total LangSummary, opts Options) string {
	var inputPrice, outputPrice, tps float64
	switch strings.ToLower(opts.LocomoPreset) {
	case "small":
		inputPrice = 0.5
		outputPrice = 2
		tps = 100
	case "large":
		inputPrice = 10
		outputPrice = 30
		tps = 30
	case "local":
		inputPrice = 0
		outputPrice = 0
		tps = 15
	default:
		inputPrice = 3
		outputPrice = 15
		tps = 50
	}
	if opts.LocomoInputPrice != nil {
		inputPrice = *opts.LocomoInputPrice
	}
	if opts.LocomoOutputPrice != nil {
		outputPrice = *opts.LocomoOutputPrice
	}
	if opts.LocomoTps != nil {
		tps = *opts.LocomoTps
	}
	tokensPerLine := 15.0
	inputPerLine := 30.0
	iterations := 1.5
	iterationWeight := 2.0
	if opts.LocomoConfig != "" {
		parts := strings.Split(opts.LocomoConfig, ",")
		if len(parts) == 5 {
			if v, err := strconv.ParseFloat(parts[0], 64); err == nil {
				tokensPerLine = v
			}
			if v, err := strconv.ParseFloat(parts[1], 64); err == nil {
				inputPerLine = v
			}
			if v, err := strconv.ParseFloat(parts[3], 64); err == nil {
				iterations = v
			}
			if v, err := strconv.ParseFloat(parts[4], 64); err == nil {
				iterationWeight = v
			}
		}
	}
	cycles := iterations
	if opts.LocomoCycles != nil {
		cycles = *opts.LocomoCycles
	} else {
		if total.Complexity > 0 {
			cycles = iterations + iterationWeight*math.Sqrt(float64(total.Complexity))/2.0
		}
	}
	inputTokens := float64(total.Lines) * inputPerLine
	outputTokens := float64(total.Lines) * tokensPerLine
	cost := (inputTokens*inputPrice + outputTokens*outputPrice) / 1e6
	genSec := outputTokens / tps
	review := 0.01
	if opts.LocomoReview != nil {
		review = *opts.LocomoReview
	}
	reviewHours := float64(total.Lines) * review / 60.0
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", opts.LocomoPreset))
	sb.WriteString(fmt.Sprintf("  Tokens Required (in/out) %.1fM / %.1fM\n", inputTokens/1e6, outputTokens/1e6))
	sb.WriteString(fmt.Sprintf("  Cost to Generate $%g\n", cost))
	sb.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", cycles))
	sb.WriteString(fmt.Sprintf("  Generation Time (serial) %.1f minutes\n", genSec/60.0))
	sb.WriteString(fmt.Sprintf("  Human Review Time %.1f hours\n", reviewHours))
	sb.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
	sb.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
	return sb.String()
}

