func init() {
	data, err := os.ReadFile("/tmp/languages_original.txt")
	if err != nil {
		data, _ = os.ReadFile("languages.txt")
	}
	if len(data) == 0 {
		languagesText = "Go (go)\nPython (py)\nJavaScript (js)\nC (c)\n"
	} else {
		languagesText = string(data)
	}
	parseLanguages(languagesText)
}

func parseLanguages(txt string) {
	extToLangs = make(map[string][]string)
	filenameToLang = make(map[string]string)
	lines := strings.Split(txt, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		open := strings.LastIndex(line, "(")
		close := strings.LastIndex(line, ")")
		if open == -1 || close == -1 || close <= open {
			continue
		}
		name := strings.TrimSpace(line[:open])
		extsStr := line[open+1 : close]
		exts := strings.Split(extsStr, ",")
		var cleanExts []string
		for _, e := range exts {
			e = strings.TrimSpace(e)
			if e == "" {
				continue
			}
			cleanExts = append(cleanExts, e)
			low := strings.ToLower(e)
			filenameToLang[low] = name
			extToLangs[low] = append(extToLangs[low], name)
		}
		langDefs = append(langDefs, LangDef{Name: name, Extensions: cleanExts})
	}
}

func isBinaryContent(content []byte) bool {
	for i, b := range content {
		if b != 0 {
			continue
		}
		if i == 0 {
			continue
		}
		if i == len(content)-1 {
			continue
		}
		if content[i-1] == '\n' {
			continue
		}
		prev := -1
		for j := i - 1; j >= 0; j-- {
			if content[j] == '\n' {
				prev = j
				break
			}
		}
		next := len(content)
		for j := i + 1; j < len(content); j++ {
			if content[j] == '\n' {
				next = j
				break
			}
		}
		line := content[prev+1 : next]
		hasAlpha := false
		for _, c := range line {
			if c == 0 {
				continue
			}
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
				hasAlpha = true
				break
			}
		}
		if hasAlpha {
			return true
		}
	}
	return false
}

func detectLanguage(path string, content []byte, opts Options, countAsMap map[string]string, remapUnknown map[string]string, remapAll map[string]string) (string, []string) {
	base := filepath.Base(path)
	lowerBase := strings.ToLower(base)
	ext := ""
	if dot := strings.LastIndex(lowerBase, "."); dot != -1 {
		ext = lowerBase[dot+1:]
	}
	if countAsMap != nil {
		if lang, ok := countAsMap[ext]; ok {
			return lang, []string{lang}
		}
		if lang, ok := countAsMap[lowerBase]; ok {
			return lang, []string{lang}
		}
		for k, v := range countAsMap {
			if strings.HasSuffix(lowerBase, "."+k) || lowerBase == k {
				return v, []string{v}
			}
		}
	}
	if lang, ok := filenameToLang[lowerBase]; ok {
		possible := extToLangs[lowerBase]
		if len(possible) == 0 {
			possible = []string{lang}
		}
		if len(remapAll) > 0 {
			contentStr := string(content)
			for needle, newLang := range remapAll {
				if strings.Contains(contentStr, needle) {
					return newLang, possible
				}
			}
		}
		return lang, possible
	}
	for token, lang := range filenameToLang {
		if strings.Contains(token, ".") {
			if strings.HasSuffix(lowerBase, "."+token) || strings.HasSuffix(lowerBase, token) {
				possible := extToLangs[token]
				return lang, possible
			}
		}
	}
	if ext != "" {
		if langs, ok := extToLangs[ext]; ok && len(langs) > 0 {
			chosen := langs[0]
			minLen := len(chosen)
			for _, l := range langs {
				if len(l) < minLen {
					minLen = len(l)
					chosen = l
				}
			}
			contentStr := string(content)
			if len(remapAll) > 0 {
				for needle, newLang := range remapAll {
					if strings.Contains(contentStr, needle) {
						return newLang, langs
					}
				}
			}
			if strings.Contains(contentStr, "AWSTemplateFormatVersion") {
				for _, l := range langs {
					if strings.Contains(l, "CloudFormation") {
						return l, langs
					}
				}
			}
			return chosen, langs
		}
	}
	contentStr := string(content)
	if strings.HasPrefix(contentStr, "#!") {
		if strings.Contains(contentStr, "python") {
			return "Python", []string{"#!"}
		}
		if strings.Contains(contentStr, "bash") || strings.Contains(contentStr, "sh") {
			return "BASH", []string{"#!"}
		}
		if strings.Contains(contentStr, "ruby") {
			return "Ruby", []string{"#!"}
		}
		if strings.Contains(contentStr, "perl") {
			return "Perl", []string{"#!"}
		}
		if strings.Contains(contentStr, "node") {
			return "JavaScript", []string{"#!"}
		}
	}
	if len(remapUnknown) > 0 {
		for needle, newLang := range remapUnknown {
			if strings.Contains(contentStr, needle) {
				return newLang, []string{"Plain Text"}
			}
		}
	}
	if len(remapAll) > 0 {
		for needle, newLang := range remapAll {
			if strings.Contains(contentStr, needle) {
				return newLang, []string{"Plain Text"}
			}
		}
	}
	return "Plain Text", []string{"Plain Text"}
}

type CountResult struct {
	Lines    int64
	Code     int64
	Comment  int64
	Blank    int64
	Complexity int64
	MaxLine  int
	MeanLine int
}

func countFile(content []byte, lang string, noComplexity bool) CountResult {
	text := string(content)
	lines := strings.Split(text, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(text, "\n") {
		lines = lines[:len(lines)-1]
	}
	var res CountResult
	res.Lines = int64(len(lines))
	maxLen := 0
	totalLen := 0
	inBlock := false
	blockStart := ""
	blockEnd := ""
	lineTokens := []string{}
	lowerLang := strings.ToLower(lang)
	switch lowerLang {
	case "go", "c", "c++", "c#", "java", "javascript", "typescript", "rust", "swift", "kotlin", "dart", "scala", "php":
		lineTokens = []string{"//"}
		blockStart = "/*"
		blockEnd = "*/"
	case "python":
		lineTokens = []string{"#"}
	case "bash", "sh", "shell", "zsh", "c shell", "fish", "korn shell":
		lineTokens = []string{"#"}
	case "ruby", "perl", "yaml", "toml", "makefile", "dockerfile", "gitignore", "ignore", "docker ignore", "ini", "properties file":
		lineTokens = []string{"#"}
	case "html", "xml", "xhtml":
		blockStart = "<!--"
		blockEnd = "-->"
	case "css", "scss", "less":
		blockStart = "/*"
		blockEnd = "*/"
	case "sql", "pl/sql":
		lineTokens = []string{"--"}
		blockStart = "/*"
		blockEnd = "*/"
	default:
		if strings.Contains(lowerLang, "bash") || strings.Contains(lowerLang, "shell") || strings.Contains(lowerLang, "python") || strings.Contains(lowerLang, "ruby") || strings.Contains(lowerLang, "perl") {
			lineTokens = []string{"#"}
		} else if strings.Contains(lowerLang, "html") || strings.Contains(lowerLang, "xml") {
			blockStart = "<!--"
			blockEnd = "-->"
		} else {
			lineTokens = []string{"//"}
			blockStart = "/*"
			blockEnd = "*/"
		}
	}
	var keywords []string
	var ops []string
	switch lowerLang {
	case "go":
		keywords = []string{"if", "for", "switch", "case", "default", "else", "go", "select"}
		ops = []string{"&&", "||"}
	case "c", "c++", "java", "c#", "javascript", "typescript", "rust", "kotlin", "swift", "php", "dart":
		keywords = []string{"if", "for", "while", "switch", "case", "else"}
		ops = []string{"&&", "||"}
	case "python":
		keywords = []string{"if", "elif", "else", "for", "while", "except", "with", "and", "or", "case"}
		ops = []string{}
	default:
		keywords = []string{"if", "for", "switch", "case", "else", "&&", "||", "and", "or"}
		ops = []string{"&&", "||"}
	}
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		ll := len(line)
		if ll > maxLen {
			maxLen = ll
		}
		totalLen += ll
		if trim == "" {
			res.Blank++
			continue
		}
		if inBlock {
			if blockEnd != "" && strings.Contains(line, blockEnd) {
				parts := strings.SplitN(line, blockEnd, 2)
				after := ""
				if len(parts) > 1 {
					after = parts[1]
				}
				if strings.TrimSpace(after) != "" {
					res.Code++
				} else {
					res.Comment++
				}
				inBlock = false
				if !noComplexity && strings.TrimSpace(after) != "" {
					res.Complexity += countComplexity(after, keywords, ops, lowerLang)
				}
			} else {
				res.Comment++
			}
			continue
		}
		if blockStart != "" && strings.Contains(line, blockStart) {
			sIdx := strings.Index(line, blockStart)
			eIdx := -1
			if blockEnd != "" {
				eIdx = strings.Index(line[sIdx+len(blockStart):], blockEnd)
			}
			before := strings.TrimSpace(line[:sIdx])
			if eIdx != -1 {
				after := line[sIdx+len(blockStart)+eIdx+len(blockEnd):]
				if before != "" || strings.TrimSpace(after) != "" {
					res.Code++
				} else {
					res.Comment++
				}
				if !noComplexity {
					if before != "" {
						res.Complexity += countComplexity(line[:sIdx], keywords, ops, lowerLang)
					}
					if strings.TrimSpace(after) != "" {
						res.Complexity += countComplexity(after, keywords, ops, lowerLang)
					}
				}
			} else {
				if before != "" {
					res.Code++
					if !noComplexity {
						res.Complexity += countComplexity(line[:sIdx], keywords, ops, lowerLang)
					}
				} else {
					res.Comment++
				}
				inBlock = true
			}
			continue
		}
		if lowerLang == "python" {
			t := strings.TrimSpace(line)
			if strings.HasPrefix(t, "\"\"\"") || strings.HasPrefix(t, "'''") {
				if strings.Count(line, "\"\"\"") >= 2 || strings.Count(line, "'''") >= 2 {
					without := strings.ReplaceAll(line, "\"\"\"", "")
					without = strings.ReplaceAll(without, "'''", "")
					if strings.TrimSpace(without) == "" {
						res.Comment++
					} else {
						res.Code++
						if !noComplexity {
							res.Complexity += countComplexity(without, keywords, ops, lowerLang)
						}
					}
				} else {
					res.Comment++
					inBlock = true
					if strings.HasPrefix(t, "\"\"\"") {
						blockStart = "\"\"\""
						blockEnd = "\"\"\""
					} else {
						blockStart = "'''"
						blockEnd = "'''"
					}
				}
				continue
			}
			if inBlock && (blockStart == "\"\"\"" || blockStart == "'''") {
				if strings.Contains(line, blockEnd) {
					res.Comment++
					inBlock = false
					blockStart = ""
					blockEnd = ""
				} else {
					res.Comment++
				}
				continue
			}
		}
		found := false
		codePart := line
		for _, tok := range lineTokens {
			idx := strings.Index(line, tok)
			if idx != -1 {
				before := line[:idx]
				if strings.Count(before, "\"")%2 == 1 || strings.Count(before, "'")%2 == 1 {
					continue
				}
				if strings.TrimSpace(before) == "" {
					res.Comment++
				} else {
					res.Code++
				}
				found = true
				codePart = before
				break
			}
		}
		if found {
			if !noComplexity {
				res.Complexity += countComplexity(codePart, keywords, ops, lowerLang)
			}
			continue
		}
		res.Code++
		if !noComplexity {
			res.Complexity += countComplexity(line, keywords, ops, lowerLang)
		}
	}
	if len(lines) > 0 {
		res.MeanLine = totalLen / len(lines)
	}
	res.MaxLine = maxLen
	return res
}

func countComplexity(code string, keywords []string, ops []string, lang string) int64 {
	var cnt int64
	for _, kw := range keywords {
		if kw == "&&" || kw == "||" || kw == "??" {
			continue
		}
		idx := 0
		for {
			pos := strings.Index(code[idx:], kw)
			if pos == -1 {
				break
			}
			abs := idx + pos
			prevOK := false
			if abs == 0 {
				prevOK = true
			} else {
				pc := code[abs-1]
				if pc == ' ' || pc == '\t' || pc == '\n' {
					prevOK = true
				}
				if lang == "python" {
					if pc == ' ' || pc == '\t' || pc == '\n' || pc == '(' || pc == ':' || pc == ';' {
						prevOK = true
					} else {
						prevOK = false
					}
				}
			}
			nextOK := false
			end := abs + len(kw)
			if end >= len(code) {
				nextOK = true
			} else {
				nc := code[end]
				if nc == ' ' || nc == '\t' || nc == '\n' || nc == '(' || nc == '{' || nc == ':' || nc == ';' {
					nextOK = true
				}
				if kw == "if" || kw == "for" || kw == "switch" {
					if nc == ' ' || nc == '(' {
						nextOK = true
					} else if kw == "for" && nc == '{' {
						nextOK = true
					} else {
						nextOK = false
					}
					if nc == '\t' {
						nextOK = false
					}
				}
			}
			if prevOK && nextOK {
				if abs > 0 {
					pc := code[abs-1]
					if (pc >= 'a' && pc <= 'z') || (pc >= 'A' && pc <= 'Z') || (pc >= '0' && pc <= '9') || pc == '_' {
						idx = abs + len(kw)
						continue
					}
				}
				if end < len(code) {
					nc := code[end]
					if (nc >= 'a' && nc <= 'z') || (nc >= 'A' && nc <= 'Z') || (nc >= '0' && nc <= '9') || nc == '_' {
						idx = abs + len(kw)
						continue
					}
				}
				cnt++
			}
			idx = abs + len(kw)
		}
	}
	for _, op := range ops {
		idx := 0
		for {
			pos := strings.Index(code[idx:], op)
			if pos == -1 {
				break
			}
			abs := idx + pos
			prevOK := false
			nextOK := false
			if abs > 0 && (code[abs-1] == ' ' || code[abs-1] == '\t') {
				prevOK = true
			}
			if abs+len(op) < len(code) && (code[abs+len(op)] == ' ' || code[abs+len(op)] == '\t') {
				nextOK = true
			}
			if prevOK && nextOK {
				cnt++
			}
			idx = abs + len(op)
		}
	}
	return cnt
}

