			inputPrice = *opts.LocomoInputPrice
		}
		if opts.LocomoOutputPrice != nil {
			outputPrice = *opts.LocomoOutputPrice
		}
		if opts.LocomoTps != nil {
			tps = *opts.LocomoTps
		}
		tokensPerLine := 15.0
		inputPerLine := 30.0
		iterations := 1.5
		iterationWeight := 2.0
		if opts.LocomoConfig != "" {
			parts := strings.Split(opts.LocomoConfig, ",")
			if len(parts) == 5 {
				if v, err := strconv.ParseFloat(parts[0], 64); err == nil {
					tokensPerLine = v
				}
				if v, err := strconv.ParseFloat(parts[1], 64); err == nil {
					inputPerLine = v
				}
				if v, err := strconv.ParseFloat(parts[3], 64); err == nil {
					iterations = v
				}
				if v, err := strconv.ParseFloat(parts[4], 64); err == nil {
					iterationWeight = v
				}
			}
		}
		cycles := iterations
		if opts.LocomoCycles != nil {
			cycles = *opts.LocomoCycles
		} else {
			if total.Complexity > 0 {
				cycles = iterations + iterationWeight*math.Sqrt(float64(total.Complexity))/2.0
			}
		}
		inputTokens := float64(total.Lines) * inputPerLine
		outputTokens := float64(total.Lines) * tokensPerLine
		costLLM := (inputTokens*inputPrice + outputTokens*outputPrice) / 1e6
		genSec := outputTokens / tps
		review := 0.01
		if opts.LocomoReview != nil {
			review = *opts.LocomoReview
		}
		reviewHours := float64(total.Lines) * review / 60.0
		mult := 1.5
		j.EstimatedLLMCost = &costLLM
		j.EstimatedLLMInputTokens = &inputTokens
		j.EstimatedLLMOutputTokens = &outputTokens
		j.EstimatedLLMGenerationSeconds = &genSec
		j.EstimatedLLMReviewHours = &reviewHours
		j.EstimatedLLMPreset = &opts.LocomoPreset
		j.EstimatedLLMAverageComplexityMultiplier = &mult
		j.EstimatedLLMCycles = &cycles
	}
	data, _ := json.Marshal(j)
	return string(data)
}

func formatCSV(summaries []LangSummary, opts Options) string {
	var sb strings.Builder
	w := csv.NewWriter(&sb)
	w.Write([]string{"Language", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Files", "ULOC"})
	for _, s := range summaries {
		w.Write([]string{s.Name, strconv.FormatInt(s.Lines, 10), strconv.FormatInt(s.Code, 10), strconv.FormatInt(s.Comment, 10), strconv.FormatInt(s.Blank, 10), strconv.FormatInt(s.Complexity, 10), strconv.FormatInt(s.Bytes, 10), strconv.FormatInt(s.Count, 10), strconv.FormatInt(s.ULOC, 10)})
	}
	w.Flush()
	return sb.String()
}

func formatCSVStream(all []FileStat, summaries []LangSummary, opts Options) string {
	var sb strings.Builder
	w := csv.NewWriter(&sb)
	w.Write([]string{"Language", "Provider", "Filename", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Uloc"})
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				w.Write([]string{s.Name, f.Location, f.Filename, strconv.FormatInt(f.Lines, 10), strconv.FormatInt(f.Code, 10), strconv.FormatInt(f.Comment, 10), strconv.FormatInt(f.Blank, 10), strconv.FormatInt(f.Complexity, 10), strconv.FormatInt(f.Bytes, 10), strconv.FormatInt(f.Uloc, 10)})
			}
		}
	} else {
		for _, f := range all {
			w.Write([]string{f.Language, f.Location, f.Filename, strconv.FormatInt(f.Lines, 10), strconv.FormatInt(f.Code, 10), strconv.FormatInt(f.Comment, 10), strconv.FormatInt(f.Blank, 10), strconv.FormatInt(f.Complexity, 10), strconv.FormatInt(f.Bytes, 10), strconv.FormatInt(f.Uloc, 10)})
		}
	}
	w.Flush()
	return sb.String()
}

func formatClocYAML(summaries []LangSummary, opts Options) string {
	var sb strings.Builder
	sb.WriteString("# https://github.com/boyter/scc/\nheader:\n  url: https://github.com/boyter/scc/\n")
	sb.WriteString(fmt.Sprintf("  version: %s\n", version))
	sb.WriteString("  elapsed_seconds: 0.001\n")
	var totalFiles, totalLines int64
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
	}
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", totalFiles))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", totalLines))
	sb.WriteString("  files_per_second: 1000\n  lines_per_second: 2000\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s:\n  name: %s\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", s.Name, s.Name, s.Code, s.Comment, s.Blank, s.Count))
	}
	sb.WriteString("SUM:\n")
	var totalCode, totalComment, totalBlank int64
	for _, s := range summaries {
		totalCode += s.Code
		totalComment += s.Comment
		totalBlank += s.Blank
	}
	sb.WriteString(fmt.Sprintf("  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", totalCode, totalComment, totalBlank, totalFiles))
	return sb.String()
}

