func formatCSV(summaries []LangSummary) string {
	var sb strings.Builder
	w := csv.NewWriter(&sb)
	w.Write([]string{"Language", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Files", "ULOC"})
	for _, s := range summaries {
		w.Write([]string{s.Name, strconv.FormatInt(s.Lines, 10), strconv.FormatInt(s.Code, 10), strconv.FormatInt(s.Comment, 10), strconv.FormatInt(s.Blank, 10), strconv.FormatInt(s.Complexity, 10), strconv.FormatInt(s.Bytes, 10), strconv.FormatInt(s.Count, 10), strconv.FormatInt(s.ULOC, 10)})
	}
	w.Flush()
	return sb.String()
}

func formatCSVStream(all []FileStat, summaries []LangSummary, opts Options) string {
	var sb strings.Builder
	w := csv.NewWriter(&sb)
	w.Write([]string{"Language", "Provider", "Filename", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Uloc"})
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				w.Write([]string{s.Name, f.Location, f.Filename, strconv.FormatInt(f.Lines, 10), strconv.FormatInt(f.Code, 10), strconv.FormatInt(f.Comment, 10), strconv.FormatInt(f.Blank, 10), strconv.FormatInt(f.Complexity, 10), strconv.FormatInt(f.Bytes, 10), strconv.FormatInt(f.Uloc, 10)})
			}
		}
	} else {
		for _, f := range all {
			w.Write([]string{f.Language, f.Location, f.Filename, strconv.FormatInt(f.Lines, 10), strconv.FormatInt(f.Code, 10), strconv.FormatInt(f.Comment, 10), strconv.FormatInt(f.Blank, 10), strconv.FormatInt(f.Complexity, 10), strconv.FormatInt(f.Bytes, 10), strconv.FormatInt(f.Uloc, 10)})
		}
	}
	w.Flush()
	return sb.String()
}

func formatClocYAML(summaries []LangSummary) string {
	var sb strings.Builder
	sb.WriteString("# https://github.com/boyter/scc/\nheader:\n  url: https://github.com/boyter/scc/\n")
	sb.WriteString(fmt.Sprintf("  version: %s\n", version))
	sb.WriteString("  elapsed_seconds: 0.001\n")
	var totalFiles, totalLines int64
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
	}
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", totalFiles))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", totalLines))
	sb.WriteString("  files_per_second: 1000\n  lines_per_second: 2000\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s:\n  name: %s\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", s.Name, s.Name, s.Code, s.Comment, s.Blank, s.Count))
	}
	sb.WriteString("SUM:\n")
	var totalCode, totalComment, totalBlank int64
	for _, s := range summaries {
