			for i, ch := range cplStr {
				rowChars[108-len(cplStr)+1+i] = ch
			}
			sb.WriteString(strings.TrimRight(string(rowChars), " ") + "\n")
		} else {
			rowChars := make([]rune, 79)
			for i := range rowChars {
