			lStr := strconv.FormatInt(s.Lines, 10)
			for i, ch := range lStr {
				rowChars[36-len(lStr)+1+i] = ch
			}
			bStr := strconv.FormatInt(s.Blank, 10)
			for i, ch := range bStr {
				rowChars[46-len(bStr)+1+i] = ch
			}
			cmtStr := strconv.FormatInt(s.Comment, 10)
