		totalFiles += s.Count
		totalLines += s.Lines
	}
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", totalFiles))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", totalLines))
	sb.WriteString("  files_per_second: 1000\n  lines_per_second: 2000\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s:\n  name: %s\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", s.Name, s.Name, s.Code, s.Comment, s.Blank, s.Count))
