func formatSQL(all []FileStat, cost, schedule, people float64, opts Options, insertOnly bool) string {
	var sb strings.Builder
	project := opts.SQLProject
	if project == "" {
		if len(all) > 0 {
			project = filepath.Dir(all[0].Location)
		} else {
			project = "."
		}
	}
	if !insertOnly {
		sb.WriteString(fmt.Sprintf("create table metadata (   -- github.com/boyter/scc v %s\n", version))
		sb.WriteString("             timestamp text,\n             Project   text,\n             elapsed_s real,\n             estimated_cost real,\n             estimated_schedule_months real,\n             estimated_people real);\n")
		sb.WriteString("create table t        (\n             Project       text   ,\n             Language      text   ,\n             File          text   ,\n             File_dirname  text   ,\n             File_basename text   ,\n             nByte         integer,\n             nBlank        integer,\n             nComment      integer,\n             nCode         integer,\n             nComplexity   integer,\n             nUloc         integer    \n);\n")
	}
	sb.WriteString("begin transaction;\n")
	for _, f := range all {
		dir := filepath.Dir(f.Location) + "/"
		sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n", project, f.Language, f.Location, dir, f.Filename, f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
	}
	sb.WriteString("commit;\nbegin transaction;\n")
	now := time.Now().Format("2006-01-02 15:04:05")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', %.6f, %f, %f, %f);\n", now, project, 0.001, cost, schedule, people))
	sb.WriteString("commit;")
	return sb.String()
}

func formatOpenMetrics(summaries []LangSummary, opts Options) string {
	var sb strings.Builder
	sb.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")
	for _, s := range summaries {
		if opts.ByFile && len(s.Files) > 0 {
			for _, f := range s.Files {
				sb.WriteString(fmt.Sprintf("scc_files{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, 1))
				sb.WriteString(fmt.Sprintf("scc_lines{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Lines))
				sb.WriteString(fmt.Sprintf("scc_code{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Code))
				sb.WriteString(fmt.Sprintf("scc_comments{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Comment))
				sb.WriteString(fmt.Sprintf("scc_blanks{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Blank))
				sb.WriteString(fmt.Sprintf("scc_complexity{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Complexity))
				sb.WriteString(fmt.Sprintf("scc_bytes{language=\"%s\",file=\"%s\"} %d\n", s.Name, f.Location, f.Bytes))
			}
		} else {
			sb.WriteString(fmt.Sprintf("scc_files{language=\"%s\"} %d\n", s.Name, s.Count))
			sb.WriteString(fmt.Sprintf("scc_lines{language=\"%s\"} %d\n", s.Name, s.Lines))
			sb.WriteString(fmt.Sprintf("scc_code{language=\"%s\"} %d\n", s.Name, s.Code))
			sb.WriteString(fmt.Sprintf("scc_comments{language=\"%s\"} %d\n", s.Name, s.Comment))
			sb.WriteString(fmt.Sprintf("scc_blanks{language=\"%s\"} %d\n", s.Name, s.Blank))
			sb.WriteString(fmt.Sprintf("scc_complexity{language=\"%s\"} %d\n", s.Name, s.Complexity))
			sb.WriteString(fmt.Sprintf("scc_bytes{language=\"%s\"} %d\n", s.Name, s.Bytes))
		}
	}
	return sb.String()
}
