			if eqIdx!=-1{
				key=arg[:eqIdx]
				val=arg[eqIdx+1:]
			}
			switch key{
			case "--avg-wage":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.AvgWage=v}
			case "--binary":
				opts.Binary=true
			case "--by-file":
				opts.ByFile=true
			case "--character","-m":
				opts.Character=true
			case "--ci":
				opts.CI=true
			case "--cocomo-project-type":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.CocomoType=val
			case "--count-as":
				if val==""{i++; if i<len(args){val=args[i]}}
				pairs:=strings.Split(val,",")
				for _,p:=range pairs{
					parts:=strings.SplitN(p,":",2)
					if len(parts)==2{
						countAsMap[strings.ToLower(strings.TrimSpace(parts[0]))]=strings.TrimSpace(parts[1])
					}
				}
			case "--count-ignore":
				opts.CountIgnore=true
			case "--currency-symbol":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.CurrencySymbol=val
			case "--debug":
				opts.Debug=true
			case "--dryness":
				opts.Dryness=true
				opts.Uloc=true
			case "--eaf":
				if val==""{i++; if i<len(args){val=args[i]}}
				if f,err:=strconv.ParseFloat(val,64);err==nil{opts.EAF=f}
			case "--exclude-dir":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeDir=append(opts.ExcludeDir,strings.Split(val,",")...)
			case "--exclude-ext":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeExt=append(opts.ExcludeExt,strings.Split(val,",")...)
			case "--exclude-file":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeFile=append(opts.ExcludeFile,strings.Split(val,",")...)
			case "--format":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.Format=val
			case "--format-multi":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.FormatMulti=val
			case "--gen":
				opts.Gen=true
			case "--include-ext":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.IncludeExt=append(opts.IncludeExt,strings.Split(val,",")...)
			case "--include-symlinks":
				opts.IncludeSymlinks=true
			case "--large-byte-count":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.LargeByteCount=v}
			case "--large-line-count":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.LargeLineCount=v}
			case "--locomo":
				opts.Locomo=true
			case "--locomo-preset":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.LocomoPreset=val
			case "--no-cocomo":
				opts.NoCocomo=true
			case "--no-complexity":
				opts.NoComplexity=true
			case "--no-duplicates":
				opts.NoDuplicates=true
			case "--no-gen":
				opts.NoGen=true
				opts.Gen=true
			case "--no-gitignore":
			case "--no-hborder":
				opts.NoHborder=true
			case "--no-large":
				opts.NoLarge=true
			case "--no-min":
				opts.NoMin=true
				opts.Min=true
			case "--no-min-gen":
				opts.NoMinGen=true
				opts.MinGen=true
			case "--no-size":
				opts.NoSize=true
			case "--not-match":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.NotMatch=append(opts.NotMatch,val)
			case "--output":
				if val==""{i++; if i<len(args){val=args[i]}}
