func formatSQL(all []FileStat, cost,schedule,people float64, opts Options, insertOnly bool) string{
	var sb strings.Builder
	project:=opts.SQLProject
	if project==""{
		if len(all)>0{
			project=filepath.Dir(all[0].Location)
		}else{
			project="."
		}
	}
	if !insertOnly{
		sb.WriteString(fmt.Sprintf("create table metadata (   -- github.com/boyter/scc v %s\n", version))
		sb.WriteString("             timestamp text,\n             Project   text,\n             elapsed_s real,\n             estimated_cost real,\n             estimated_schedule_months real,\n             estimated_people real);\n")
		sb.WriteString("create table t        (\n             Project       text   ,\n             Language      text   ,\n             File          text   ,\n             File_dirname  text   ,\n             File_basename text   ,\n             nByte         integer,\n             nBlank        integer,\n             nComment      integer,\n             nCode         integer,\n             nComplexity   integer,\n             nUloc         integer    \n);\n")
	}
	sb.WriteString("begin transaction;\n")
	for _, f:=range all{
		dir:=filepath.Dir(f.Location)+"/"
		sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n", project, f.Language, f.Location, dir, f.Filename, f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
	}
	sb.WriteString("commit;\nbegin transaction;\n")
	now:=time.Now().Format("2006-01-02 15:04:05")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', %.6f, %f, %f, %f);\n", now, project, 0.001, cost, schedule, people))
	sb.WriteString("commit;")
	return sb.String()
}

