var extToLangs map[string][]string
var filenameToLang map[string]string

func init() {
	data, err := os.ReadFile("/tmp/languages_original.txt")
	if err != nil {
		languagesText = "Go (go)\n"
	} else {
		languagesText = string(data)
	}
	parseLanguages(languagesText)
}

func parseLanguages(txt string) {
	extToLangs = make(map[string][]string)
	filenameToLang = make(map[string]string)
	lines := strings.Split(txt, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		open := strings.LastIndex(line, "(")
		close := strings.LastIndex(line, ")")
		if open == -1 || close == -1 || close <= open {
			continue
		}
		name := strings.TrimSpace(line[:open])
		extsStr := line[open+1 : close]
		exts := strings.Split(extsStr, ",")
		for _, e := range exts {
			e = strings.TrimSpace(e)
			if e == "" {
				continue
			}
			low := strings.ToLower(e)
			filenameToLang[low] = name
			extToLangs[low] = append(extToLangs[low], name)
		}
	}
}

func isBinaryContent(content []byte) bool {
	for i, b := range content {
		if b != 0 {
			continue
		}
		if i == 0 || i == len(content)-1 {
			continue
		}
		if content[i-1] == '\n' {
			continue
		}
		prev := -1
		for j := i - 1; j >= 0; j-- {
			if content[j] == '\n' {
				prev = j
				break
			}
		}
		next := len(content)
		for j := i + 1; j < len(content); j++ {
			if content[j] == '\n' {
				next = j
				break
			}
		}
		line := content[prev+1 : next]
		hasAlpha := false
		for _, c := range line {
			if c == 0 {
				continue
			}
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
				hasAlpha = true
				break
			}
		}
		if hasAlpha {
			return true
		}
	}
	return false
}

func detectLanguage(path string, content []byte, opts Options, countAsMap map[string]string) (string, []string) {
	base := filepath.Base(path)
	lowerBase := strings.ToLower(base)
	ext := ""
	if dot := strings.LastIndex(lowerBase, "."); dot != -1 {
		ext = lowerBase[dot+1:]
	}
	if countAsMap != nil {
		if lang, ok := countAsMap[ext]; ok {
			return lang, []string{lang}
		}
		if lang, ok := countAsMap[lowerBase]; ok {
			return lang, []string{lang}
		}
	}
	if lang, ok := filenameToLang[lowerBase]; ok {
		possible := extToLangs[lowerBase]
		if len(possible) == 0 {
			possible = []string{lang}
		}
		return lang, possible
	}
	for token, lang := range filenameToLang {
		if strings.Contains(token, ".") {
			if strings.HasSuffix(lowerBase, "."+token) || strings.HasSuffix(lowerBase, token) {
				return lang, extToLangs[token]
			}
		}
	}
	if ext != "" {
		if langs, ok := extToLangs[ext]; ok && len(langs) > 0 {
			chosen := langs[0]
			minLen := len(chosen)
			for _, l := range langs {
				if len(l) < minLen {
					minLen = len(l)
					chosen = l
				}
			}
			s := string(content)
			if strings.Contains(s, "AWSTemplateFormatVersion") {
				for _, l := range langs {
					if strings.Contains(l, "CloudFormation") {
						return l, langs
					}
				}
			}
			return chosen, langs
		}
	}
	return "Plain Text", []string{"Plain Text"}
}

type CountResult struct {
	Lines, Code, Comment, Blank, Complexity int64
}

func countFile(content []byte, lang string, noComplexity bool) CountResult {
	text := string(content)
	lines := strings.Split(text, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(text, "\n") {
		lines = lines[:len(lines)-1]
	}
	var res CountResult
	res.Lines = int64(len(lines))
	inBlock := false
	blockStart := ""
	blockEnd := ""
	lineTokens := []string{}
	lowerLang := strings.ToLower(lang)
	switch lowerLang {
	case "go", "c", "c++", "java", "javascript", "typescript", "rust":
		lineTokens = []string{"//"}
		blockStart = "/*"
		blockEnd = "*/"
	case "python":
		lineTokens = []string{"#"}
	case "bash", "sh", "shell":
		lineTokens = []string{"#"}
	default:
		if strings.Contains(lowerLang, "bash") || strings.Contains(lowerLang, "shell") || strings.Contains(lowerLang, "python") {
			lineTokens = []string{"#"}
		} else if strings.Contains(lowerLang, "html") {
			blockStart = "<!--"
			blockEnd = "-->"
		} else {
			lineTokens = []string{"//"}
			blockStart = "/*"
			blockEnd = "*/"
		}
	}
	var keywords []string
	var ops []string
	if lowerLang == "go" {
		keywords = []string{"if", "for", "switch", "case", "else", "go", "select"}
		ops = []string{"&&", "||"}
	} else if lowerLang == "python" {
		keywords = []string{"if", "elif", "else", "for", "while", "except", "with", "and", "or"}
	} else {
		keywords = []string{"if", "for", "while", "switch", "case", "else"}
		ops = []string{"&&", "||"}
	}
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		if trim == "" {
			res.Blank++
			continue
		}
		if inBlock {
			if blockEnd != "" && strings.Contains(line, blockEnd) {
				parts := strings.SplitN(line, blockEnd, 2)
				after := ""
				if len(parts) > 1 {
					after = parts[1]
				}
				if strings.TrimSpace(after) != "" {
					res.Code++
				} else {
					res.Comment++
				}
				inBlock = false
				if !noComplexity && strings.TrimSpace(after) != "" {
					res.Complexity += countComplexity(after, keywords, ops, lowerLang)
				}
			} else {
				res.Comment++
			}
			continue
		}
		if blockStart != "" && strings.Contains(line, blockStart) {
			sIdx := strings.Index(line, blockStart)
			eIdx := -1
			if blockEnd != "" {
				eIdx = strings.Index(line[sIdx+len(blockStart):], blockEnd)
			}
			before := strings.TrimSpace(line[:sIdx])
			if eIdx != -1 {
				after := line[sIdx+len(blockStart)+eIdx+len(blockEnd):]
				if before != "" || strings.TrimSpace(after) != "" {
					res.Code++
				} else {
					res.Comment++
				}
				if !noComplexity {
					if before != "" {
						res.Complexity += countComplexity(line[:sIdx], keywords, ops, lowerLang)
					}
					if strings.TrimSpace(after) != "" {
						res.Complexity += countComplexity(after, keywords, ops, lowerLang)
					}
				}
			} else {
				if before != "" {
					res.Code++
					if !noComplexity {
						res.Complexity += countComplexity(line[:sIdx], keywords, ops, lowerLang)
					}
				} else {
					res.Comment++
				}
				inBlock = true
			}
			continue
		}
		if lowerLang == "python" {
			t := strings.TrimSpace(line)
			if strings.HasPrefix(t, "\"\"\"") || strings.HasPrefix(t, "'''") {
				if strings.Count(line, "\"\"\"") >= 2 || strings.Count(line, "'''") >= 2 {
					without := strings.ReplaceAll(line, "\"\"\"", "")
					without = strings.ReplaceAll(without, "'''", "")
					if strings.TrimSpace(without) == "" {
						res.Comment++
					} else {
						res.Code++
					}
				} else {
					res.Comment++
					inBlock = true
					if strings.HasPrefix(t, "\"\"\"") {
						blockStart = "\"\"\""
						blockEnd = "\"\"\""
					} else {
						blockStart = "'''"
						blockEnd = "'''"
					}
				}
				continue
			}
			if inBlock && (blockStart == "\"\"\"" || blockStart == "'''") {
				if strings.Contains(line, blockEnd) {
					res.Comment++
					inBlock = false
					blockStart = ""
					blockEnd = ""
				} else {
					res.Comment++
				}
				continue
			}
		}
		found := false
		codePart := line
		for _, tok := range lineTokens {
			idx := strings.Index(line, tok)
			if idx != -1 {
				before := line[:idx]
				if strings.Count(before, "\"")%2 == 1 {
					continue
				}
				if strings.TrimSpace(before) == "" {
					res.Comment++
				} else {
					res.Code++
				}
				found = true
				codePart = before
				break
			}
		}
		if found {
			if !noComplexity {
				res.Complexity += countComplexity(codePart, keywords, ops, lowerLang)
			}
			continue
		}
		res.Code++
		if !noComplexity {
			res.Complexity += countComplexity(line, keywords, ops, lowerLang)
		}
	}
	return res
}

func countComplexity(code string, keywords []string, ops []string, lang string) int64 {
	var cnt int64
	for _, kw := range keywords {
		if kw == "&&" || kw == "||" {
			continue
		}
		idx := 0
		for {
			pos := strings.Index(code[idx:], kw)
			if pos == -1 {
				break
			}
			abs := idx + pos
			prevOK := abs == 0 || code[abs-1] == ' ' || code[abs-1] == '\t' || code[abs-1] == '\n'
			nextOK := false
			end := abs + len(kw)
			if end >= len(code) {
				nextOK = true
			} else {
				nc := code[end]
				if nc == ' ' || nc == '(' || nc == '{' || nc == ':' {
					nextOK = true
				}
				if kw == "if" || kw == "for" {
					if nc == ' ' || nc == '(' {
						nextOK = true
					} else if kw == "for" && nc == '{' {
						nextOK = true
					} else {
						nextOK = false
					}
					if nc == '\t' {
						nextOK = false
					}
				}
			}
			if prevOK && nextOK {
				if abs > 0 {
					pc := code[abs-1]
					if (pc >= 'a' && pc <= 'z') || (pc >= 'A' && pc <= 'Z') || (pc >= '0' && pc <= '9') || pc == '_' {
						idx = abs + len(kw)
						continue
					}
				}
				if end < len(code) {
					nc := code[end]
					if (nc >= 'a' && nc <= 'z') || (nc >= 'A' && nc <= 'Z') || (nc >= '0' && nc <= '9') || nc == '_' {
						idx = abs + len(kw)
						continue
					}
				}
				cnt++
			}
			idx = abs + len(kw)
		}
	}
	for _, op := range ops {
		idx := 0
		for {
			pos := strings.Index(code[idx:], op)
			if pos == -1 {
				break
			}
			abs := idx + pos
			if abs > 0 && (code[abs-1] == ' ' || code[abs-1] == '\t') && abs+len(op) < len(code) && (code[abs+len(op)] == ' ' || code[abs+len(op)] == '\t') {
				cnt++
			}
			idx = abs + len(op)
		}
	}
	return cnt
}

func formatWithComma(n int64) string {
	s := fmt.Sprintf("%d", n)
	var out []rune
	c := 0
	for i := len(s) - 1; i >= 0; i-- {
		if c == 3 {
			out = append([]rune{','}, out...)
			c = 0
		}
		out = append([]rune{rune(s[i])}, out...)
		c++
	}
	return string(out)
}

func computeCOCOMO(code int64, opts Options) (float64, float64, float64) {
	kloc := float64(code) / 1000.0
	var a, b, c, d float64
	switch strings.ToLower(opts.CocomoType) {
	case "semi-detached":
		a = 3.0
		b = 1.12
		c = 2.5
		d = 0.35
	case "embedded":
		a = 3.6
		b = 1.20
		c = 2.5
		d = 0.32
	default:
		a = 2.4
		b = 1.05
		c = 2.5
		d = 0.38
	}
	effort := a * math.Pow(kloc, b) * opts.EAF
	sched := c * math.Pow(effort, d)
	people := 0.0
	if sched != 0 {
		people = effort / sched
	}
	cost := effort / 12.0 * float64(opts.AvgWage) * opts.Overhead
	return cost, sched, people
}

func formatSize(bytes int64, unit string) string {
	switch strings.ToLower(unit) {
	case "binary":
		return fmt.Sprintf("%d bytes, %.3f megabytes (BINARY)", bytes, float64(bytes)/(1024*1024))
	default:
		return fmt.Sprintf("%d bytes, %.3f megabytes (SI)", bytes, float64(bytes)/1e6)
	}
}

func formatTabular(summaries []LangSummary, total LangSummary, cost, schedule, people float64, opts Options, wide bool) string {
	var sb strings.Builder
	bChar := "─"
	if opts.CI {
		bChar = "-"
	}
	bLen := 79
	if wide {
		bLen = 141
	}
	printBorder := func() {
		if !opts.NoHborder {
			sb.WriteString(strings.Repeat(bChar, bLen) + "\n")
		}
	}
	printBorder()
	if wide {
		sb.WriteString("Language                              Files     Lines   Blanks  Comments     Code Complexity Complexity/Lines\n")
	} else {
		sb.WriteString("Language            Files       Lines    Blanks  Comments       Code Complexity\n")
	}
	printBorder()
	for _, s := range summaries {
		if wide {
			cpl := 0.0
			if s.Lines > 0 {
				cpl = float64(s.Complexity) / float64(s.Lines)
			}
			rc := make([]rune, 109)
			for i := range rc {
				rc[i] = ' '
			}
			for i, ch := range s.Name {
				if i < 38 {
					rc[i] = ch
				}
			}
			fStr := strconv.FormatInt(s.Count, 10)
			for i, ch := range fStr {
				rc[42-len(fStr)+1+i] = ch
			}
			lStr := strconv.FormatInt(s.Lines, 10)
			for i, ch := range lStr {
				rc[52-len(lStr)+1+i] = ch
			}
			bStr := strconv.FormatInt(s.Blank, 10)
			for i, ch := range bStr {
				rc[61-len(bStr)+1+i] = ch
			}
			cStr := strconv.FormatInt(s.Comment, 10)
			for i, ch := range cStr {
				rc[71-len(cStr)+1+i] = ch
			}
			codeStr := strconv.FormatInt(s.Code, 10)
			for i, ch := range codeStr {
				rc[80-len(codeStr)+1+i] = ch
			}
			compStr := strconv.FormatInt(s.Complexity, 10)
			for i, ch := range compStr {
				rc[91-len(compStr)+1+i] = ch
			}
			cplStr := fmt.Sprintf("%.2f", cpl)
			for i, ch := range cplStr {
				rc[108-len(cplStr)+1+i] = ch
			}
			sb.WriteString(strings.TrimRight(string(rc), " ") + "\n")
			if opts.ByFile {
				for _, f := range s.Files {
					rc2 := make([]rune, 109)
					for i := range rc2 {
						rc2[i] = ' '
					}
					for i, ch := range f.Location {
						if i < 38 {
							rc2[i] = ch
						}
					}
					ls := strconv.FormatInt(f.Lines, 10)
					for i, ch := range ls {
						rc2[52-len(ls)+1+i] = ch
					}
					bs := strconv.FormatInt(f.Blank, 10)
					for i, ch := range bs {
						rc2[61-len(bs)+1+i] = ch
					}
					cs := strconv.FormatInt(f.Comment, 10)
					for i, ch := range cs {
						rc2[71-len(cs)+1+i] = ch
					}
					codeS := strconv.FormatInt(f.Code, 10)
					for i, ch := range codeS {
						rc2[80-len(codeS)+1+i] = ch
					}
					compS := strconv.FormatInt(f.Complexity, 10)
					for i, ch := range compS {
						rc2[91-len(compS)+1+i] = ch
					}
					sb.WriteString(strings.TrimRight(string(rc2), " ") + "\n")
				}
			}
		} else {
			rc := make([]rune, 79)
			for i := range rc {
				rc[i] = ' '
			}
			for i, ch := range s.Name {
				if i < 20 {
					rc[i] = ch
				}
			}
			fStr := strconv.FormatInt(s.Count, 10)
			for i, ch := range fStr {
				rc[24-len(fStr)+1+i] = ch
			}
			lStr := strconv.FormatInt(s.Lines, 10)
			for i, ch := range lStr {
				rc[36-len(lStr)+1+i] = ch
			}
			bStr := strconv.FormatInt(s.Blank, 10)
			for i, ch := range bStr {
				rc[46-len(bStr)+1+i] = ch
			}
			cmtStr := strconv.FormatInt(s.Comment, 10)
			for i, ch := range cmtStr {
				rc[56-len(cmtStr)+1+i] = ch
			}
			codeStr := strconv.FormatInt(s.Code, 10)
			for i, ch := range codeStr {
				rc[67-len(codeStr)+1+i] = ch
			}
			compStr := strconv.FormatInt(s.Complexity, 10)
			for i, ch := range compStr {
				rc[78-len(compStr)+1+i] = ch
			}
			sb.WriteString(string(rc) + "\n")
			if opts.ByFile {
				// border between language and files
				if !opts.NoHborder {
					sb.WriteString(strings.Repeat(bChar, 79) + "\n")
				}
				for _, f := range s.Files {
					rc2 := make([]rune, 79)
					for i := range rc2 {
						rc2[i] = ' '
					}
					for i, ch := range f.Location {
						if i < 32 {
							rc2[i] = ch
						}
					}
					ls := strconv.FormatInt(f.Lines, 10)
					for i, ch := range ls {
						rc2[36-len(ls)+1+i] = ch
					}
					bs := strconv.FormatInt(f.Blank, 10)
					for i, ch := range bs {
						rc2[46-len(bs)+1+i] = ch
					}
					cs := strconv.FormatInt(f.Comment, 10)
					for i, ch := range cs {
						rc2[56-len(cs)+1+i] = ch
					}
					codeS := strconv.FormatInt(f.Code, 10)
					for i, ch := range codeS {
						rc2[67-len(codeS)+1+i] = ch
					}
					compS := strconv.FormatInt(f.Complexity, 10)
					for i, ch := range compS {
						rc2[78-len(compS)+1+i] = ch
					}
					sb.WriteString(string(rc2) + "\n")
				}
			}
		}
	}
	printBorder()
	if wide {
		rc := make([]rune, 109)
		for i := range rc {
			rc[i] = ' '
		}
		for i, ch := range "Total" {
			rc[i] = ch
		}
		fs := strconv.FormatInt(total.Count, 10)
		for i, ch := range fs {
			rc[42-len(fs)+1+i] = ch
		}
		ls := strconv.FormatInt(total.Lines, 10)
		for i, ch := range ls {
			rc[52-len(ls)+1+i] = ch
		}
		bs := strconv.FormatInt(total.Blank, 10)
		for i, ch := range bs {
			rc[61-len(bs)+1+i] = ch
		}
		cs := strconv.FormatInt(total.Comment, 10)
		for i, ch := range cs {
			rc[71-len(cs)+1+i] = ch
		}
		codeS := strconv.FormatInt(total.Code, 10)
		for i, ch := range codeS {
			rc[80-len(codeS)+1+i] = ch
		}
		compS := strconv.FormatInt(total.Complexity, 10)
		for i, ch := range compS {
			rc[91-len(compS)+1+i] = ch
		}
		cpl := 0.0
		if total.Lines > 0 {
			cpl = float64(total.Complexity) / float64(total.Lines)
		}
		cplS := fmt.Sprintf("%.2f", cpl)
		for i, ch := range cplS {
			rc[108-len(cplS)+1+i] = ch
		}
		sb.WriteString(strings.TrimRight(string(rc), " ") + "\n")
	} else {
		rc := make([]rune, 79)
		for i := range rc {
			rc[i] = ' '
		}
		for i, ch := range "Total" {
			rc[i] = ch
		}
		fs := strconv.FormatInt(total.Count, 10)
		for i, ch := range fs {
			rc[24-len(fs)+1+i] = ch
		}
		ls := strconv.FormatInt(total.Lines, 10)
		for i, ch := range ls {
			rc[36-len(ls)+1+i] = ch
		}
		bs := strconv.FormatInt(total.Blank, 10)
		for i, ch := range bs {
			rc[46-len(bs)+1+i] = ch
		}
		cs := strconv.FormatInt(total.Comment, 10)
		for i, ch := range cs {
			rc[56-len(cs)+1+i] = ch
		}
		codeS := strconv.FormatInt(total.Code, 10)
		for i, ch := range codeS {
			rc[67-len(codeS)+1+i] = ch
		}
		compS := strconv.FormatInt(total.Complexity, 10)
		for i, ch := range compS {
			rc[78-len(compS)+1+i] = ch
		}
		sb.WriteString(string(rc) + "\n")
	}
	printBorder()
	if !opts.NoCocomo {
		sb.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%s\n", opts.CocomoType, opts.CurrencySymbol, formatWithComma(int64(cost))))
		sb.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", opts.CocomoType, schedule))
		sb.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", opts.CocomoType, people))
		printBorder()
	}
	if !opts.NoSize {
		sb.WriteString("Processed " + formatSize(total.Bytes, opts.SizeUnit) + "\n")
		printBorder()
	}
	return sb.String()
}

