var extToLangs map[string][]string
var filenameToLang map[string]string

func init(){
	data, _ := os.ReadFile("/tmp/languages_original.txt")
	if len(data)==0{
		languagesText="Go (go)\n"
	}else{
		languagesText=string(data)
	}
	parseLanguages(languagesText)
}

func parseLanguages(txt string){
	extToLangs=make(map[string][]string)
	filenameToLang=make(map[string]string)
	for _, line := range strings.Split(txt, "\n"){
		line=strings.TrimSpace(line)
		if line==""{continue}
		open:=strings.LastIndex(line,"(")
		close:=strings.LastIndex(line,")")
		if open==-1||close==-1||close<=open{continue}
		name:=strings.TrimSpace(line[:open])
		extsStr:=line[open+1:close]
		for _, e := range strings.Split(extsStr, ","){
			e=strings.TrimSpace(e)
			if e==""{continue}
			low:=strings.ToLower(e)
			filenameToLang[low]=name
			extToLangs[low]=append(extToLangs[low], name)
		}
	}
}

func isBinaryContent(content []byte) bool{
	for i,b:=range content{
		if b!=0{
			continue
		}
		if i==0||i==len(content)-1{continue}
		if content[i-1]=='\n'{continue}
		prev:=-1
		for j:=i-1;j>=0;j--{
			if content[j]=='\n'{prev=j;break}
		}
		next:=len(content)
		for j:=i+1;j<len(content);j++{
			if content[j]=='\n'{next=j;break}
		}
		line:=content[prev+1:next]
		hasAlpha:=false
		for _,c:=range line{
			if c==0{continue}
			if (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9'){hasAlpha=true;break}
		}
		if hasAlpha{return true}
	}
	return false
}

func detectLanguage(path string, content []byte, opts Options, countAsMap map[string]string, remapUnknown map[string]string, remapAll map[string]string) (string, []string){
	base:=filepath.Base(path)
	lowerBase:=strings.ToLower(base)
	ext:=""
	if dot:=strings.LastIndex(lowerBase,".");dot!=-1{
		ext=lowerBase[dot+1:]
	}
	if countAsMap!=nil{
		if lang, ok:=countAsMap[ext];ok{return lang, []string{lang}}
		if lang, ok:=countAsMap[lowerBase];ok{return lang, []string{lang}}
	}
	if lang, ok:=filenameToLang[lowerBase];ok{
		possible:=extToLangs[lowerBase]
		if len(possible)==0{possible=[]string{lang}}
		if len(remapAll)>0{
			s:=string(content)
			for needle,newLang:=range remapAll{
				if strings.Contains(s, needle){return newLang, possible}
			}
		}
		return lang, possible
	}
	for token, lang := range filenameToLang{
		if strings.Contains(token, "."){
			if strings.HasSuffix(lowerBase, "."+token)||strings.HasSuffix(lowerBase, token){
				return lang, extToLangs[token]
			}
		}
	}
	if ext!=""{
		if langs, ok:=extToLangs[ext];ok&&len(langs)>0{
			chosen:=langs[0]
			minLen:=len(chosen)
			for _, l:=range langs{
				if len(l)<minLen{minLen=len(l);chosen=l}
			}
			s:=string(content)
			if len(remapAll)>0{
				for needle,newLang:=range remapAll{
					if strings.Contains(s, needle){return newLang, langs}
				}
			}
			if strings.Contains(s, "AWSTemplateFormatVersion"){
				for _, l:=range langs{
					if strings.Contains(l,"CloudFormation"){return l, langs}
				}
			}
			return chosen, langs
		}
	}
	s:=string(content)
	if strings.HasPrefix(s, "#!"){
		if strings.Contains(s,"python"){return "Python", []string{"#!"}}
		if strings.Contains(s,"bash")||strings.Contains(s,"sh"){return "BASH", []string{"#!"}}
	}
	if len(remapUnknown)>0{
		for needle,newLang:=range remapUnknown{
			if strings.Contains(s, needle){return newLang, []string{"Plain Text"}}
		}
	}
	if len(remapAll)>0{
		for needle,newLang:=range remapAll{
			if strings.Contains(s, needle){return newLang, []string{"Plain Text"}}
		}
	}
	return "Plain Text", []string{"Plain Text"}
}

type CountResult struct{Lines,Code,Comment,Blank,Complexity int64}

func countFile(content []byte, lang string, noComplexity bool) CountResult{
	text:=string(content)
	lines:=strings.Split(text,"\n")
	if len(lines)>0&&lines[len(lines)-1]==""&&strings.HasSuffix(text,"\n"){
		lines=lines[:len(lines)-1]
	}
	var res CountResult
	res.Lines=int64(len(lines))
	inBlock:=false
	blockStart:=""
	blockEnd:=""
	lineTokens:=[]string{}
	lowerLang:=strings.ToLower(lang)
	switch lowerLang{
	case "go","c","c++","java","javascript","typescript","rust":
		lineTokens=[]string{"//"}
		blockStart="/*"
		blockEnd="*/"
	case "python":
		lineTokens=[]string{"#"}
	case "bash","sh","shell":
		lineTokens=[]string{"#"}
	default:
		if strings.Contains(lowerLang,"bash")||strings.Contains(lowerLang,"shell")||strings.Contains(lowerLang,"python"){
			lineTokens=[]string{"#"}
		}else if strings.Contains(lowerLang,"html"){
			blockStart="<!--"
			blockEnd="-->"
		}else{
			lineTokens=[]string{"//"}
			blockStart="/*"
			blockEnd="*/"
		}
	}
	var keywords []string
	var ops []string
	if lowerLang=="go"{
		keywords=[]string{"if","for","switch","case","else","go","select"}
		ops=[]string{"&&","||"}
	}else if lowerLang=="python"{
		keywords=[]string{"if","elif","else","for","while","except","with","and","or"}
	}else{
		keywords=[]string{"if","for","while","switch","case","else"}
		ops=[]string{"&&","||"}
	}
	for _, line := range lines{
		trim:=strings.TrimSpace(line)
		if trim==""{res.Blank++;continue}
		if inBlock{
			if blockEnd!=""&&strings.Contains(line,blockEnd){
				parts:=strings.SplitN(line,blockEnd,2)
				after:=""
				if len(parts)>1{after=parts[1]}
				if strings.TrimSpace(after)!=""{res.Code++}else{res.Comment++}
				inBlock=false
				if !noComplexity&&strings.TrimSpace(after)!=""{
					res.Complexity+=countComplexity(after,keywords,ops,lowerLang)
				}
			}else{res.Comment++}
			continue
		}
		if blockStart!=""&&strings.Contains(line,blockStart){
			sIdx:=strings.Index(line,blockStart)
			eIdx:=-1
			if blockEnd!=""{eIdx=strings.Index(line[sIdx+len(blockStart):],blockEnd)}
			before:=strings.TrimSpace(line[:sIdx])
			if eIdx!=-1{
				after:=line[sIdx+len(blockStart)+eIdx+len(blockEnd):]
				if before!=""||strings.TrimSpace(after)!=""{res.Code++}else{res.Comment++}
				if !noComplexity{
					if before!=""{res.Complexity+=countComplexity(line[:sIdx],keywords,ops,lowerLang)}
					if strings.TrimSpace(after)!=""{res.Complexity+=countComplexity(after,keywords,ops,lowerLang)}
				}
			}else{
				if before!=""{
					res.Code++
					if !noComplexity{res.Complexity+=countComplexity(line[:sIdx],keywords,ops,lowerLang)}
				}else{res.Comment++}
				inBlock=true
			}
			continue
		}
		if lowerLang=="python"{
			t:=strings.TrimSpace(line)
			if strings.HasPrefix(t,"\"\"\"")||strings.HasPrefix(t,"'''"){
				if strings.Count(line,"\"\"\"")>=2||strings.Count(line,"'''")>=2{
					without:=strings.ReplaceAll(line,"\"\"\"","")
					without=strings.ReplaceAll(without,"'''","")
					if strings.TrimSpace(without)==""{res.Comment++}else{res.Code++}
				}else{
					res.Comment++
					inBlock=true
					if strings.HasPrefix(t,"\"\"\""){blockStart="\"\"\"";blockEnd="\"\"\""}else{blockStart="'''";blockEnd="'''"}
				}
				continue
			}
			if inBlock&&(blockStart=="\"\"\""||blockStart=="'''"){
				if strings.Contains(line,blockEnd){
					res.Comment++
					inBlock=false
					blockStart=""
					blockEnd=""
				}else{res.Comment++}
				continue
			}
		}
		found:=false
		codePart:=line
		for _, tok:=range lineTokens{
			idx:=strings.Index(line,tok)
			if idx!=-1{
				before:=line[:idx]
				if strings.Count(before,"\"")%2==1{continue}
				if strings.TrimSpace(before)==""{res.Comment++}else{res.Code++}
				found=true
				codePart=before
				break
			}
		}
		if found{
			if !noComplexity{res.Complexity+=countComplexity(codePart,keywords,ops,lowerLang)}
			continue
		}
		res.Code++
		if !noComplexity{res.Complexity+=countComplexity(line,keywords,ops,lowerLang)}
	}
	return res
}

func countComplexity(code string, keywords []string, ops []string, lang string) int64{
	var cnt int64
	for _, kw:=range keywords{
		if kw=="&&"||kw=="||"{continue}
		idx:=0
		for{
			pos:=strings.Index(code[idx:],kw)
			if pos==-1{break}
			abs:=idx+pos
			prevOK:=abs==0||code[abs-1]==' '||code[abs-1]=='\t'||code[abs-1]=='\n'
			nextOK:=false
			end:=abs+len(kw)
			if end>=len(code){nextOK=true}else{
				nc:=code[end]
				if nc==' '||nc=='('||nc=='{'||nc==':'{nextOK=true}
				if kw=="if"||kw=="for"{
					if nc==' '||nc=='('{nextOK=true}else if kw=="for"&&nc=='{'{nextOK=true}else{nextOK=false}
					if nc=='\t'{nextOK=false}
				}
			}
			if prevOK&&nextOK{
				if abs>0{
					pc:=code[abs-1]
					if (pc>='a'&&pc<='z')||(pc>='A'&&pc<='Z')||(pc>='0'&&pc<='9')||pc=='_'{idx=abs+len(kw);continue}
				}
				if end<len(code){
					nc:=code[end]
					if (nc>='a'&&nc<='z')||(nc>='A'&&nc<='Z')||(nc>='0'&&nc<='9')||nc=='_'{idx=abs+len(kw);continue}
				}
				cnt++
			}
			idx=abs+len(kw)
		}
	}
	for _, op:=range ops{
		idx:=0
		for{
			pos:=strings.Index(code[idx:],op)
			if pos==-1{break}
			abs:=idx+pos
			if abs>0&&(code[abs-1]==' '||code[abs-1]=='\t')&&abs+len(op)<len(code)&&(code[abs+len(op)]==' '||code[abs+len(op)]=='\t'){
				cnt++
			}
			idx=abs+len(op)
		}
	}
	return cnt
}

func formatWithComma(n int64) string{
	s:=fmt.Sprintf("%d",n)
	var out []rune
	c:=0
	for i:=len(s)-1;i>=0;i--{
		if c==3{out=append([]rune{','},out...);c=0}
		out=append([]rune{rune(s[i])},out...)
		c++
	}
	return string(out)
}

func computeCOCOMO(code int64, opts Options) (float64,float64,float64){
	kloc:=float64(code)/1000.0
	var a,b,c,d float64
	switch strings.ToLower(opts.CocomoType){
	case "semi-detached":
		a=3.0;b=1.12;c=2.5;d=0.35
	case "embedded":
		a=3.6;b=1.20;c=2.5;d=0.32
	default:
		a=2.4;b=1.05;c=2.5;d=0.38
	}
	effort:=a*math.Pow(kloc,b)*opts.EAF
	sched:=c*math.Pow(effort,d)
	people:=0.0
	if sched!=0{people=effort/sched}
	cost:=effort/12.0*float64(opts.AvgWage)*opts.Overhead
	return cost,sched,people
}

func formatSize(bytes int64, unit string) string{
	switch strings.ToLower(unit){
	case "binary":
		return fmt.Sprintf("%d bytes, %.3f megabytes (BINARY)", bytes, float64(bytes)/(1024*1024))
	default:
		return fmt.Sprintf("%d bytes, %.3f megabytes (SI)", bytes, float64(bytes)/1e6)
	}
}

func formatTabular(summaries []LangSummary, total LangSummary, cost, schedule, people float64, opts Options, wide bool) string{
	var sb strings.Builder
	bChar:="─"
	if opts.CI{bChar="-"}
	bLen:=79
	if wide{
		if opts.CI{bLen=141}else{bLen=109}
	}
	printBorder:=func(){
		if !opts.NoHborder{sb.WriteString(strings.Repeat(bChar,bLen)+"\n")}
	}
	printBorder()
	if wide{
		sb.WriteString("Language                              Files     Lines   Blanks  Comments     Code Complexity Complexity/Lines\n")
	}else{
		sb.WriteString("Language            Files       Lines    Blanks  Comments       Code Complexity\n")
	}
	printBorder()
	for _, s:=range summaries{
		if wide{
			cpl:=0.0
			if s.Lines>0{cpl=float64(s.Complexity)/float64(s.Lines)}
			rc:=make([]rune,109)
