func formatClocYAML(summaries []LangSummary) string{
	var sb strings.Builder
	sb.WriteString("# https://github.com/boyter/scc/\nheader:\n  url: https://github.com/boyter/scc/\n  version: 3.7.0\n  elapsed_seconds: 0.001\n")
	var tf,tl int64
	for _, s:=range summaries{tf+=s.Count;tl+=s.Lines}
	sb.WriteString(fmt.Sprintf("  n_files: %d\n  n_lines: %d\n  files_per_second: 1000\n  lines_per_second: 2000\n",tf,tl))
	for _, s:=range summaries{
		sb.WriteString(fmt.Sprintf("%s:\n  name: %s\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n",s.Name,s.Name,s.Code,s.Comment,s.Blank,s.Count))
	}
	sb.WriteString("SUM:\n")
	var tc,tcm,tb int64
	for _, s:=range summaries{tc+=s.Code;tcm+=s.Comment;tb+=s.Blank}
	sb.WriteString(fmt.Sprintf("  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n",tc,tcm,tb,tf))
	return sb.String()
}

