	}
	return sb.String()
}

func main(){
	args:=os.Args[1:]
	opts:=Options{
		AvgWage:56286, CocomoType:"organic", CurrencySymbol:"$", EAF:1.0,
		ExcludeDir:[]string{".git",".hg",".svn"},
		ExcludeFile:[]string{"package-lock.json","Cargo.lock","yarn.lock","pubspec.lock","Podfile.lock","pnpm-lock.yaml"},
		Format:"tabular", GeneratedMarkers:[]string{"do not edit","<auto-generated />"},
		LargeByteCount:1000000, LargeLineCount:40000, LocomoPreset:"medium", MinGenLineLength:255, Overhead:2.4, Sort:"files", SizeUnit:"si",
	}
	countAsMap:=make(map[string]string)
	remapUnknown:=make(map[string]string)
	remapAll:=make(map[string]string)
	var paths []string
	i:=0
	for i < len(args){
		arg:=args[i]
		if arg=="--help"||arg=="-h"{fmt.Print(helpText);return}
		if arg=="--version"{fmt.Printf("scc version %s\n",version);return}
		if arg=="--languages"||arg=="-l"{fmt.Print(languagesText);return}
		if strings.HasPrefix(arg,"--"){
			eqIdx:=strings.Index(arg,"=")
			key:=arg
			val:=""
			if eqIdx!=-1{key=arg[:eqIdx];val=arg[eqIdx+1:]}
			switch key{
			case "--avg-wage":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.AvgWage=v}
			case "--binary":
				opts.Binary=true
			case "--by-file":
				opts.ByFile=true
			case "--character":
				opts.Character=true
			case "--ci":
				opts.CI=true
			case "--cocomo-project-type":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.CocomoType=val
			case "--count-as":
				if val==""{i++; if i<len(args){val=args[i]}}
				for _, p:=range strings.Split(val,","){
					parts:=strings.SplitN(p,":",2)
					if len(parts)==2{countAsMap[strings.ToLower(strings.TrimSpace(parts[0]))]=strings.TrimSpace(parts[1])}
				}
			case "--count-ignore":
				opts.CountIgnore=true
			case "--currency-symbol":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.CurrencySymbol=val
			case "--eaf":
				if val==""{i++; if i<len(args){val=args[i]}}
				if f,err:=strconv.ParseFloat(val,64);err==nil{opts.EAF=f}
			case "--exclude-dir":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeDir=append(opts.ExcludeDir, strings.Split(val,",")...)
			case "--exclude-ext":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeExt=append(opts.ExcludeExt, strings.Split(val,",")...)
			case "--exclude-file":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.ExcludeFile=append(opts.ExcludeFile, strings.Split(val,",")...)
			case "--format":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.Format=val
			case "--format-multi":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.FormatMulti=val
			case "--gen":
				opts.Gen=true
			case "--include-ext":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.IncludeExt=append(opts.IncludeExt, strings.Split(val,",")...)
			case "--include-symlinks":
				opts.IncludeSymlinks=true
			case "--large-byte-count":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.LargeByteCount=v}
			case "--large-line-count":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.LargeLineCount=v}
			case "--locomo":
				opts.Locomo=true
			case "--locomo-preset":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.LocomoPreset=val
			case "--no-cocomo":
				opts.NoCocomo=true
			case "--no-complexity":
				opts.NoComplexity=true
			case "--no-duplicates":
				opts.NoDuplicates=true
			case "--no-gen":
				opts.NoGen=true
				opts.Gen=true
			case "--no-hborder":
				opts.NoHborder=true
			case "--no-large":
				opts.NoLarge=true
			case "--no-min":
				opts.NoMin=true
				opts.Min=true
			case "--no-min-gen":
				opts.NoMinGen=true
				opts.MinGen=true
			case "--no-size":
				opts.NoSize=true
			case "--not-match":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.NotMatch=append(opts.NotMatch,val)
			case "--output":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.Output=val
			case "--overhead":
				if val==""{i++; if i<len(args){val=args[i]}}
				if f,err:=strconv.ParseFloat(val,64);err==nil{opts.Overhead=f}
			case "--percent":
				opts.Percent=true
			case "--size-unit":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.SizeUnit=val
			case "--sloccount-format":
				opts.SloccountFormat=true
			case "--sort":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.Sort=val
			case "--sql-project":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.SQLProject=val
			case "--uloc":
				opts.Uloc=true
			case "--wide":
				opts.Wide=true
			}
		}else if strings.HasPrefix(arg,"-")&&len(arg)>1{
			switch arg{
			case "-m":
				opts.Character=true
			case "-a":
				opts.Dryness=true
				opts.Uloc=true
			case "-c":
				opts.NoComplexity=true
			case "-d":
				opts.NoDuplicates=true
			case "-p":
				opts.Percent=true
			case "-u":
				opts.Uloc=true
			case "-w":
				opts.Wide=true
			case "-l":
				fmt.Print(languagesText)
				return
			case "-h":
				fmt.Print(helpText)
				return
			default:
				if strings.HasPrefix(arg,"-x"){
					if len(arg)>2{opts.ExcludeExt=append(opts.ExcludeExt, strings.Split(arg[2:],",")...)}else{i++; if i<len(args){opts.ExcludeExt=append(opts.ExcludeExt, strings.Split(args[i],",")...)}}
				}else if strings.HasPrefix(arg,"-f"){
					if len(arg)>2{opts.Format=arg[2:]}else{i++; opts.Format=args[i]}
				}
			}
		}else{
			paths=append(paths,arg)
		}
		i++
	}
	if len(paths)==0{paths=[]string{"."}}
	allFiles:=[]FileStat{}
	seenHashes:=make(map[string]bool)
	for _, root:=range paths{
		info, err:=os.Lstat(root)
		if err!=nil{continue}
		if !info.IsDir(){
			if info.Mode()&fs.ModeSymlink!=0&&!opts.IncludeSymlinks{continue}
			if shouldExcludeFile(root,opts){continue}
			stat,ok:=processFile(root,root,opts,countAsMap,remapUnknown,remapAll,seenHashes)
			if ok{allFiles=append(allFiles,stat)}
		}else{
			filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error{
				if err!=nil{return nil}
				if d.IsDir(){
					base:=d.Name()
					for _, ex:=range opts.ExcludeDir{
						if strings.ToLower(base)==strings.ToLower(ex){return fs.SkipDir}
					}
					return nil
				}
				if d.Type()&fs.ModeSymlink!=0&&!opts.IncludeSymlinks{return nil}
				if shouldExcludeFile(p,opts){return nil}
				stat,ok:=processFile(p,root,opts,countAsMap,remapUnknown,remapAll,seenHashes)
				if ok{allFiles=append(allFiles,stat)}
				return nil
			})
		}
	}
	langMap:=make(map[string]*LangSummary)
	for _, f:=range allFiles{
		langName:=f.Language
		if f.Minified&&(opts.NoMin||opts.NoMinGen){continue}
		if f.Generated&&(opts.NoGen||opts.NoMinGen){continue}
		if opts.NoLarge&&(f.Bytes>int64(opts.LargeByteCount)||f.Lines>int64(opts.LargeLineCount)){continue}
		if _,ok:=langMap[langName];!ok{langMap[langName]=&LangSummary{Name:langName}}
		ls:=langMap[langName]
		ls.Bytes+=f.Bytes
		ls.Lines+=f.Lines
		ls.Code+=f.Code
		ls.Comment+=f.Comment
		ls.Blank+=f.Blank
		ls.Complexity+=f.Complexity
		ls.Count++
		if opts.ByFile{ls.Files=append(ls.Files,f)}
	}
	var summaries []LangSummary
	for _, v:=range langMap{
		if !opts.ByFile{v.Files=[]FileStat{}}
		summaries=append(summaries,*v)
	}
	sort.Slice(summaries, func(i,j int)bool{
		switch strings.ToLower(opts.Sort){
		case "name":
			return strings.ToLower(summaries[i].Name)<strings.ToLower(summaries[j].Name)
		case "lines":
			return summaries[i].Lines>summaries[j].Lines
		default:
			if summaries[i].Count!=summaries[j].Count{return summaries[i].Count>summaries[j].Count}
			return strings.ToLower(summaries[i].Name)<strings.ToLower(summaries[j].Name)
		}
	})
	var total LangSummary
	total.Name="Total"
	for _, s:=range summaries{
		total.Bytes+=s.Bytes
		total.Lines+=s.Lines
		total.Code+=s.Code
		total.Comment+=s.Comment
		total.Blank+=s.Blank
		total.Complexity+=s.Complexity
		total.Count+=s.Count
	}
	cost,sched,people:=computeCOCOMO(total.Code,opts)
	output:=""
	isWide:=opts.Wide||strings.ToLower(opts.Format)=="wide"
	switch strings.ToLower(opts.Format){
	case "json":
		output=formatJSON(summaries)
	case "json2":
		output=formatJSON2(summaries,cost,sched,people,opts)
	case "csv":
		output=formatCSV(summaries)
	case "csv-stream":
		output=formatCSVStream(allFiles,summaries,opts)
	case "cloc-yaml":
		output=formatClocYAML(summaries)
	case "html":
		output=formatHTML(summaries,cost,sched,people,opts,false)
	case "html-table":
		output=formatHTML(summaries,cost,sched,people,opts,true)
	case "sql":
		output=formatSQL(allFiles,cost,sched,people,opts,false)
	case "sql-insert":
		output=formatSQL(allFiles,cost,sched,people,opts,true)
	case "openmetrics":
		output=formatOpenMetrics(summaries,opts)
	case "wide":
		output=formatTabular(summaries,total,cost,sched,people,opts,true)
	default:
		if isWide{
			output=formatTabular(summaries,total,cost,sched,people,opts,true)
		}else{
			output=formatTabular(summaries,total,cost,sched,people,opts,false)
		}
	}
	if opts.FormatMulti!=""{
		pairs:=strings.Split(opts.FormatMulti,",")
		for _, p:=range pairs{
			parts:=strings.SplitN(strings.TrimSpace(p),":",2)
			if len(parts)!=2{continue}
			fm:=strings.TrimSpace(parts[0])
			dest:=strings.TrimSpace(parts[1])
			var out string
			switch strings.ToLower(fm){
			case "json":
				out=formatJSON(summaries)
			case "json2":
				out=formatJSON2(summaries,cost,sched,people,opts)
			case "csv":
				out=formatCSV(summaries)
			case "csv-stream":
				out=formatCSVStream(allFiles,summaries,opts)
			case "cloc-yaml":
				out=formatClocYAML(summaries)
			case "html":
				out=formatHTML(summaries,cost,sched,people,opts,false)
			case "html-table":
				out=formatHTML(summaries,cost,sched,people,opts,true)
			case "sql":
				out=formatSQL(allFiles,cost,sched,people,opts,false)
			case "sql-insert":
				out=formatSQL(allFiles,cost,sched,people,opts,true)
			case "openmetrics":
				out=formatOpenMetrics(summaries,opts)
			case "wide":
				out=formatTabular(summaries,total,cost,sched,people,opts,true)
			default:
				out=formatTabular(summaries,total,cost,sched,people,opts,false)
			}
			if dest=="stdout"{fmt.Print(out)}else{os.WriteFile(dest,[]byte(out),0644)}
		}
		return
	}
	if opts.Output!=""{
		os.WriteFile(opts.Output,[]byte(output),0644)
		return
	}
	fmt.Print(output)
}

func shouldExcludeFile(path string, opts Options) bool{
	base:=filepath.Base(path)
	lowerBase:=strings.ToLower(base)
	for _, ef:=range opts.ExcludeFile{
		ef=strings.TrimSpace(ef)
		if ef==""{continue}
		if matched,_:=filepath.Match(strings.ToLower(ef),lowerBase);matched{return true}
		if lowerBase==strings.ToLower(ef){return true}
	}
	ext:=""
	if dot:=strings.LastIndex(lowerBase,".");dot!=-1{ext=lowerBase[dot+1:]}
	for _, ex:=range opts.ExcludeExt{
		ex=strings.TrimSpace(strings.ToLower(ex))
		if ex==""{continue}
		if ext==ex{return true}
	}
	if len(opts.IncludeExt)>0{
		found:=false
		for _, inc:=range opts.IncludeExt{
			inc=strings.TrimSpace(strings.ToLower(inc))
			if ext==inc||lowerBase==inc{found=true;break}
		}
		if !found{return true}
	}
	for _, pat:=range opts.NotMatch{
		if matched,_:=regexp.MatchString(pat,path);matched{return true}
		if matched,_:=regexp.MatchString(pat,base);matched{return true}
	}
	return false
}

func processFile(path string, root string, opts Options, countAsMap map[string]string, remapUnknown map[string]string, remapAll map[string]string, seenHashes map[string]bool) (FileStat, bool){
	content, err:=os.ReadFile(path)
	if err!=nil{return FileStat{},false}
	bytesCount:=int64(len(content))
	if !opts.Binary{
		if isBinaryContent(content){return FileStat{},false}
	}
	linesCount:=int64(strings.Count(string(content), "\n"))
	if len(content)>0&&!strings.HasSuffix(string(content), "\n"){linesCount++}
	if opts.NoLarge{
		if bytesCount>int64(opts.LargeByteCount)||linesCount>int64(opts.LargeLineCount){return FileStat{},false}
	}
	lang, possible:=detectLanguage(path, content, opts, countAsMap, remapUnknown, remapAll)
	isGen:=false
	head:=string(content)
	if len(head)>1000{head=head[:1000]}
	lowerHead:=strings.ToLower(head)
	for _, m:=range opts.GeneratedMarkers{
		if strings.Contains(lowerHead, strings.ToLower(m)){isGen=true;break}
	}
	isMin:=false
	if linesCount>0{
		avg:=float64(bytesCount)/float64(linesCount)
		if avg>float64(opts.MinGenLineLength){isMin=true}
	}
	if opts.NoDuplicates{
		h:=sha256.Sum256(content)
		hs:=fmt.Sprintf("%x",h)
		if seenHashes[hs]{return FileStat{},false}
		seenHashes[hs]=true
	}
	countRes:=countFile(content, lang, opts.NoComplexity)
	base:=filepath.Base(path)
	ext:=filepath.Ext(base)
	if ext!=""{ext=ext[1:]}else{ext=base}
	lowerBase:=strings.ToLower(base)
	if lowerBase==".gitignore"||lowerBase==".ignore"{
		if !opts.CountIgnore{return FileStat{},false}
	}
	stat:=FileStat{Language:lang,PossibleLanguages:possible,Filename:base,Extension:ext,Location:path,Bytes:bytesCount,Lines:countRes.Lines,Code:countRes.Code,Comment:countRes.Comment,Blank:countRes.Blank,Complexity:countRes.Complexity,Minified:isMin,Generated:isGen}
	return stat,true
}
