			case "--large-line-count":
				if val==""{i++; if i<len(args){val=args[i]}}
				if v,err:=strconv.Atoi(val);err==nil{opts.LargeLineCount=v}
			case "--locomo":
				opts.Locomo=true
			case "--locomo-preset":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.LocomoPreset=val
			case "--no-cocomo":
				opts.NoCocomo=true
			case "--no-complexity":
				opts.NoComplexity=true
			case "--no-duplicates":
				opts.NoDuplicates=true
			case "--no-gen":
				opts.NoGen=true
				opts.Gen=true
			case "--no-hborder":
				opts.NoHborder=true
			case "--no-large":
				opts.NoLarge=true
			case "--no-min":
				opts.NoMin=true
				opts.Min=true
			case "--no-min-gen":
				opts.NoMinGen=true
				opts.MinGen=true
			case "--no-size":
				opts.NoSize=true
			case "--not-match":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.NotMatch=append(opts.NotMatch,val)
			case "--output":
				if val==""{i++; if i<len(args){val=args[i]}}
				opts.Output=val
