				opts.Uloc=true
			case "--wide":
				opts.Wide=true
			}
		}else if strings.HasPrefix(arg,"-")&&len(arg)>1{
			switch arg{
			case "-m":
				opts.Character=true
			case "-a":
				opts.Dryness=true
				opts.Uloc=true
			case "-c":
				opts.NoComplexity=true
			case "-d":
				opts.NoDuplicates=true
			case "-p":
				opts.Percent=true
			case "-u":
				opts.Uloc=true
			case "-w":
				opts.Wide=true
			case "-l":
				fmt.Print(languagesText)
				return
			case "-h":
				fmt.Print(helpText)
				return
			default:
				if strings.HasPrefix(arg,"-x"){
					if len(arg)>2{opts.ExcludeExt=append(opts.ExcludeExt, strings.Split(arg[2:],",")...)}else{i++; if i<len(args){opts.ExcludeExt=append(opts.ExcludeExt, strings.Split(args[i],",")...)}}
				}else if strings.HasPrefix(arg,"-f"){
					if len(arg)>2{opts.Format=arg[2:]}else{i++; opts.Format=args[i]}
				}
			}
		}else{
			paths=append(paths,arg)
		}
		i++
	}
	if len(paths)==0{paths=[]string{"."}}
	allFiles:=[]FileStat{}
	seenHashes:=make(map[string]bool)
	for _, root:=range paths{
		info, err:=os.Lstat(root)
		if err!=nil{continue}
		if !info.IsDir(){
			if info.Mode()&fs.ModeSymlink!=0&&!opts.IncludeSymlinks{continue}
			if shouldExcludeFile(root,opts){continue}
			stat,ok:=processFile(root,root,opts,countAsMap,remapUnknown,remapAll,seenHashes)
			if ok{allFiles=append(allFiles,stat)}
		}else{
			filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error{
				if err!=nil{return nil}
				if d.IsDir(){
					base:=d.Name()
					for _, ex:=range opts.ExcludeDir{
